import type { DailyVerse } from "@shared/schema";

export const versesEN: DailyVerse[] = [
  { id: "1", verse: "For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life.", reference: "John 3:16", devotional: "God's love for you is beyond measure. He gave His most precious gift so that you could live forever with Him. Let this truth fill your heart with gratitude and hope today.", prayer: "Lord, thank You for Your incredible love. Help me to receive it fully and share it with others. In Jesus' name, Amen.", date: "" },
  { id: "2", verse: "For I know the thoughts that I think toward you, saith the Lord, thoughts of peace, and not of evil, to give you an expected end.", reference: "Jeremiah 29:11", devotional: "God has a beautiful plan for your life. Even when circumstances seem uncertain, trust that He is working all things together for your good. His plans are filled with hope.", prayer: "Heavenly Father, thank You for the plans You have for me. Help me to trust You even when I cannot see the path ahead. In Jesus' name, Amen.", date: "" },
  { id: "3", verse: "The Lord is my shepherd; I shall not want. He maketh me to lie down in green pastures: he leadeth me beside the still waters. He restoreth my soul.", reference: "Psalm 23:1-3", devotional: "Our Good Shepherd provides everything we need. He leads us to places of rest and restoration. When life feels overwhelming, remember that He is always guiding you toward peace.", prayer: "Lord, You are my Shepherd. Lead me to places of rest and peace. Restore my soul and renew my strength. Amen.", date: "" },
  { id: "4", verse: "Trust in the Lord with all thine heart; and lean not unto thine own understanding. In all thy ways acknowledge him, and he shall direct thy paths.", reference: "Proverbs 3:5-6", devotional: "God invites us to trust Him completely, not relying on our limited perspective. When we surrender our plans to Him, He guides our steps with perfect wisdom.", prayer: "Father, I choose to trust You with all my heart. Guide my steps today and make my paths straight. Amen.", date: "" },
  { id: "5", verse: "I can do all things through Christ which strengtheneth me.", reference: "Philippians 4:13", devotional: "Your strength comes not from yourself but from Christ living in you. No challenge is too great when you rely on His power. He equips you for every task He calls you to.", prayer: "Jesus, thank You for being my strength. Help me to rely on You in every challenge I face today. Amen.", date: "" },
  { id: "6", verse: "And we know that all things work together for good to them that love God, to them who are the called according to his purpose.", reference: "Romans 8:28", devotional: "Even in difficult seasons, God is working behind the scenes for your good. Nothing in your life is wasted when placed in His hands. Trust His process and His timing.", prayer: "Lord, help me to trust that You are working all things for my good, even when I cannot see it. Amen.", date: "" },
  { id: "7", verse: "Have not I commanded thee? Be strong and of a good courage; be not afraid, neither be thou dismayed: for the Lord thy God is with thee whithersoever thou goest.", reference: "Joshua 1:9", devotional: "God commands courage because He promises His presence. You never face any situation alone. The Creator of the universe walks beside you every step of the way.", prayer: "Father, fill me with courage and strength. Thank You that You are always with me. Remove fear and discouragement from my heart. Amen.", date: "" },
  { id: "8", verse: "The Lord is my light and my salvation; whom shall I fear? the Lord is the strength of my life; of whom shall I be afraid?", reference: "Psalm 27:1", devotional: "When God is your light, no darkness can overcome you. When He is your salvation, no enemy can defeat you. Stand firm in the confidence that He is your protector and refuge.", prayer: "Lord, You are my light and salvation. Remove all fear from my heart and help me to trust in Your protection. Amen.", date: "" },
  { id: "9", verse: "But they that wait upon the Lord shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint.", reference: "Isaiah 40:31", devotional: "When you feel exhausted and weak, place your hope in God. He promises to renew your strength supernaturally. Wait on Him and watch Him lift you above your circumstances.", prayer: "Lord, I place my hope in You. Renew my strength today. Help me to soar above my challenges on wings of faith. Amen.", date: "" },
  { id: "10", verse: "Come unto me, all ye that labour and are heavy laden, and I will give you rest.", reference: "Matthew 11:28", devotional: "Jesus extends a personal invitation to lay down your burdens at His feet. You don't have to carry the weight of the world. He offers true rest for your weary soul.", prayer: "Jesus, I come to You with all my burdens. Give me Your rest and peace. I lay everything at Your feet today. Amen.", date: "" },
  { id: "11", verse: "The Lord is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit.", reference: "Psalm 34:18", devotional: "In your deepest pain, God draws near. He is not distant or indifferent to your suffering. He tenderly ministers to broken hearts and brings healing to crushed spirits.", prayer: "Lord, draw near to me in my brokenness. Heal my heart and restore my spirit. Thank You for Your tender compassion. Amen.", date: "" },
  { id: "12", verse: "For we walk by faith, not by sight.", reference: "2 Corinthians 5:7", devotional: "Faith means trusting God even when you cannot see the outcome. It is the confident assurance that God is faithful to His promises. Step forward boldly in faith today.", prayer: "Father, strengthen my faith. Help me to walk by faith and not by sight, trusting You in every step. Amen.", date: "" },
  { id: "13", verse: "Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God.", reference: "Philippians 4:6", devotional: "God invites you to exchange your anxiety for His peace through prayer. Instead of worrying, bring every concern to Him with a grateful heart. He cares about every detail of your life.", prayer: "Lord, I give You all my worries and anxieties. Fill me with Your peace as I bring my requests before You with thanksgiving. Amen.", date: "" },
  { id: "14", verse: "And the peace of God, which passeth all understanding, shall keep your hearts and minds through Christ Jesus.", reference: "Philippians 4:7", devotional: "God's peace is supernatural. It goes beyond human logic and guards your innermost being. When you entrust your life to Christ, His peace becomes a fortress around your heart.", prayer: "Father, let Your peace that surpasses all understanding guard my heart and mind today. In Christ Jesus, Amen.", date: "" },
  { id: "15", verse: "The Lord is my strength and my shield; my heart trusted in him, and I am helped: therefore my heart greatly rejoiceth; and with my song will I praise him.", reference: "Psalm 28:7", devotional: "God is both your strength for the journey and your shield against harm. When your heart fully trusts in Him, you experience His help in tangible ways. He never fails those who depend on Him.", prayer: "Lord, be my strength and shield today. I place my trust fully in You, knowing You will help me. Amen.", date: "" },
  { id: "16", verse: "Casting all your care upon him; for he careth for you.", reference: "1 Peter 5:7", devotional: "You are deeply loved by God, and He wants to carry your burdens. Don't hold onto worry when you can give it to the One who cares for you more than anyone else ever could.", prayer: "Father, I cast all my anxieties upon You right now. Thank You for caring for me so deeply. Amen.", date: "" },
  { id: "17", verse: "God is our refuge and strength, a very present help in trouble.", reference: "Psalm 46:1", devotional: "In every storm of life, God is your safe place. He is not just available sometimes but is ever-present in your time of need. Run to Him and find unshakable strength.", prayer: "Lord, You are my refuge and strength. Be my ever-present help in every trouble I face. Amen.", date: "" },
  { id: "18", verse: "In the beginning God created the heaven and the earth.", reference: "Genesis 1:1", devotional: "The God who created everything from nothing is the same God who holds your life in His hands. If He can speak the universe into existence, He can handle whatever you are facing today.", prayer: "Creator God, I stand in awe of Your power. The same hands that made the heavens hold my life. I trust You completely. Amen.", date: "" },
  { id: "19", verse: "So God created man in his own image, in the image of God created he him; male and female created he them.", reference: "Genesis 1:27", devotional: "You are created in the image of God Himself. This gives you inherent worth, dignity, and purpose. You are not an accident but a masterpiece designed by the Creator.", prayer: "Father, thank You for creating me in Your image. Help me to see myself and others through Your eyes of love. Amen.", date: "" },
  { id: "20", verse: "The name of the Lord is a strong tower: the righteous runneth into it, and is safe.", reference: "Proverbs 18:10", devotional: "God's very name is a place of protection. When you call upon Him, you are running into an impenetrable fortress. No enemy can reach you when you are sheltered in His name.", prayer: "Lord, I run to Your name for safety. Be my fortified tower and my place of refuge today. Amen.", date: "" },
  { id: "21", verse: "Delight thyself also in the Lord; and he shall give thee the desires of thine heart.", reference: "Psalm 37:4", devotional: "When you find your greatest joy in God, He shapes your desires to align with His perfect will. Delighting in Him transforms what you want into what He wants to give you.", prayer: "Lord, help me to delight in You above all else. Align my desires with Your perfect will for my life. Amen.", date: "" },
  { id: "22", verse: "The Lord shall fight for you, and ye shall hold your peace.", reference: "Exodus 14:14", devotional: "Sometimes the greatest act of faith is to be still and let God fight your battles. You don't have to strive or struggle. Trust that He is working on your behalf.", prayer: "Lord, I choose to be still and trust that You are fighting for me. Give me patience and faith in Your timing. Amen.", date: "" },
  { id: "23", verse: "For where two or three are gathered together in my name, there am I in the midst of them.", reference: "Matthew 18:20", devotional: "Christ promises His presence whenever believers unite in His name. There is power in community and prayer together. You are never alone in your faith journey.", prayer: "Jesus, thank You for Your presence when we gather in Your name. Bless our fellowship and unite us in love. Amen.", date: "" },
  { id: "24", verse: "Being confident of this very thing, that he which hath begun a good work in you will perform it until the day of Jesus Christ.", reference: "Philippians 1:6", devotional: "God is not finished with you yet. The work He started in your life will be completed. Every struggle is part of His process of making you more like Christ.", prayer: "Father, thank You that You are not done with me. Complete the good work You have begun in my life. Amen.", date: "" },
  { id: "25", verse: "But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith, meekness, temperance: against such there is no law.", reference: "Galatians 5:22-23", devotional: "As you walk with the Holy Spirit, His character blossoms within you. These beautiful qualities are not achieved by effort but grown through surrender to God's Spirit.", prayer: "Holy Spirit, produce Your fruit in my life. Grow love, joy, peace, and all Your character within me. Amen.", date: "" },
  { id: "26", verse: "No weapon that is formed against thee shall prosper; and every tongue that shall rise against thee in judgment thou shalt condemn.", reference: "Isaiah 54:17", devotional: "God has declared that no attack against you will succeed. His protection covers you completely. Stand firm in this promise and refuse to be shaken by the enemy's schemes.", prayer: "Lord, I stand on Your promise that no weapon formed against me shall prosper. You are my defender. Amen.", date: "" },
  { id: "27", verse: "The Lord bless thee, and keep thee: The Lord make his face shine upon thee, and be gracious unto thee.", reference: "Numbers 6:24-25", devotional: "This ancient blessing is God's heart for you today. He wants to bless you, keep you safe, shine His favor upon you, and pour out His grace. Receive His blessing with open arms.", prayer: "Lord, I receive Your blessing today. Let Your face shine upon me and be gracious to me. Amen.", date: "" },
  { id: "28", verse: "What shall we then say to these things? If God be for us, who can be against us?", reference: "Romans 8:31", devotional: "When the Almighty God is on your side, no opposition can ultimately prevail. This is not a wishful thought but a powerful truth. The God of the universe is for you.", prayer: "Father, thank You for being for me. With You on my side, I have nothing to fear. Strengthen my confidence in You. Amen.", date: "" },
  { id: "29", verse: "These things I have spoken unto you, that in me ye might have peace. In the world ye shall have tribulation: but be of good cheer; I have overcome the world.", reference: "John 16:33", devotional: "Jesus is honest about the reality of trouble, but He also declares total victory. His peace is available to you in the midst of any storm because He has already won.", prayer: "Jesus, thank You for overcoming the world. Give me Your peace in every trouble I face. I take heart because You have won. Amen.", date: "" },
  { id: "30", verse: "Thy word is a lamp unto my feet, and a light unto my path.", reference: "Psalm 119:105", devotional: "God's Word illuminates your next step. You may not see the entire journey, but His truth gives you enough light for today. Let Scripture guide your decisions and your direction.", prayer: "Lord, let Your Word light my path today. Guide my steps through Your truth and wisdom. Amen.", date: "" },
  { id: "31", verse: "For by grace are ye saved through faith; and that not of yourselves: it is the gift of God.", reference: "Ephesians 2:8", devotional: "Salvation is a free gift from God, not something you can earn. His grace reached down to you when you could not reach up to Him. Receive this gift with a grateful heart.", prayer: "Father, thank You for the gift of salvation by grace through faith. Help me to live in gratitude for Your amazing gift. Amen.", date: "" },
  { id: "32", verse: "Be still, and know that I am God: I will be exalted among the heathen, I will be exalted in the earth.", reference: "Psalm 46:10", devotional: "In a world of noise and busyness, God calls you to stillness. In that quiet place, you discover who He truly is. Pause, breathe, and know that He is God over all.", prayer: "Lord, help me to be still before You. In the silence, reveal Yourself to me. You are God and I trust You. Amen.", date: "" },
  { id: "33", verse: "Therefore if any man be in Christ, he is a new creature: old things are passed away; behold, all things are become new.", reference: "2 Corinthians 5:17", devotional: "In Christ, you are made brand new. Your past does not define you. God has given you a fresh start and a new identity. Walk in the freedom of who you are in Him.", prayer: "Lord Jesus, thank You for making me a new creation. Help me to leave the old behind and walk in newness of life. Amen.", date: "" },
  { id: "34", verse: "The grass withereth, the flower fadeth: but the word of our God shall stand for ever.", reference: "Isaiah 40:8", devotional: "Everything in this world is temporary, but God's Word stands eternal. Build your life on His unchanging truth and you will never be shaken.", prayer: "Lord, help me to anchor my life in Your eternal Word. When everything else fades, Your truth remains forever. Amen.", date: "" },
  { id: "35", verse: "Charity suffereth long, and is kind; charity envieth not; charity vaunteth not itself, is not puffed up.", reference: "1 Corinthians 13:4", devotional: "True love, as God defines it, is selfless and enduring. It reflects God's own character toward us. Ask Him to grow this kind of love in your heart today.", prayer: "Father, teach me to love as You love. Make me patient, kind, and humble in all my relationships. Amen.", date: "" },
  { id: "36", verse: "Create in me a clean heart, O God; and renew a right spirit within me.", reference: "Psalm 51:10", devotional: "God is in the business of renewal. He can take a weary, stained heart and make it pure again. Come to Him honestly and let Him restore your inner life.", prayer: "God, create in me a clean heart. Renew a right spirit within me. Wash me and make me new. Amen.", date: "" },
  { id: "37", verse: "For the wages of sin is death; but the gift of God is eternal life through Jesus Christ our Lord.", reference: "Romans 6:23", devotional: "Sin leads to death, but God offers life as a free gift. Through Jesus Christ, the penalty has been paid and eternal life is yours. This is the good news of the gospel.", prayer: "Lord, thank You for the gift of eternal life through Jesus. Help me to share this good news with everyone I meet. Amen.", date: "" },
  { id: "38", verse: "But seek ye first the kingdom of God, and his righteousness; and all these things shall be added unto you.", reference: "Matthew 6:33", devotional: "When you prioritize God's kingdom above everything else, He takes care of all your needs. Put Him first and watch how He provides in ways you never imagined.", prayer: "Father, help me to seek Your kingdom first in everything. I trust You to provide for all my needs. Amen.", date: "" },
  { id: "39", verse: "The Lord is gracious, and full of compassion; slow to anger, and of great mercy.", reference: "Psalm 145:8", devotional: "God's character is filled with grace and compassion. He is patient with your failures and generous with His love. Rest in knowing that His heart toward you is always good.", prayer: "Lord, thank You for Your grace and compassion. Help me to reflect Your patience and love to others. Amen.", date: "" },
  { id: "40", verse: "Jesus saith unto him, I am the way, the truth, and the life: no man cometh unto the Father, but by me.", reference: "John 14:6", devotional: "Jesus is the only path to God the Father. In a world of many voices and philosophies, His declaration stands firm. He is not one of many ways but the only way.", prayer: "Jesus, You are the Way, the Truth, and the Life. Help me to follow You faithfully every day. Amen.", date: "" },
  { id: "41", verse: "A man's heart deviseth his way: but the Lord directeth his steps.", reference: "Proverbs 16:9", devotional: "While it is wise to make plans, ultimately God directs your path. Surrender your plans to Him and trust that His direction is always better than your own.", prayer: "Lord, I surrender my plans to You. Establish my steps according to Your perfect will. Amen.", date: "" },
  { id: "42", verse: "The Lord thy God in the midst of thee is mighty; he will save, he will rejoice over thee with joy; he will rest in his love, he will joy over thee with singing.", reference: "Zephaniah 3:17", devotional: "God is not only mighty to save but He also rejoices over you with singing. Imagine the Creator of the universe delighting in you. His love is personal, powerful, and tender.", prayer: "Father, thank You for rejoicing over me with gladness. Let me feel Your love quieting my soul today. Amen.", date: "" },
  { id: "43", verse: "And above all things have fervent charity among yourselves: for charity shall cover the multitude of sins.", reference: "1 Peter 4:8", devotional: "Deep, genuine love has the power to heal and restore relationships. When we love as Christ loves us, we extend grace and forgiveness that covers offenses. Let love lead your actions.", prayer: "Lord, help me to love others deeply and sincerely. Let my love reflect Your grace and forgiveness. Amen.", date: "" },
  { id: "44", verse: "Take therefore no thought for the morrow: for the morrow shall take thought for the things of itself. Sufficient unto the day is the evil thereof.", reference: "Matthew 6:34", devotional: "Jesus teaches us to live one day at a time. Tomorrow's worries can steal today's peace. Focus on what God has placed before you today and trust Him with tomorrow.", prayer: "Lord, free me from worry about tomorrow. Help me to live fully in today, trusting You with the future. Amen.", date: "" },
  { id: "45", verse: "Blessed is the man that trusteth in the Lord, and whose hope the Lord is.", reference: "Jeremiah 17:7", devotional: "There is a special blessing reserved for those who place their trust in God. When your confidence rests in Him rather than in circumstances, you find unshakable peace.", prayer: "Father, I place my trust and confidence in You alone. Bless me as I lean on Your faithfulness. Amen.", date: "" },
  { id: "46", verse: "The Lord is my rock, and my fortress, and my deliverer; my God, my strength, in whom I will trust; my buckler, and the horn of my salvation, and my high tower.", reference: "Psalm 18:2", devotional: "God is your solid foundation when everything else shakes. He is your fortress against the enemy and your deliverer from every snare. You are secure in Him.", prayer: "Lord, You are my rock and fortress. I take refuge in You. Deliver me from every trouble and keep me safe. Amen.", date: "" },
  { id: "47", verse: "I will instruct thee and teach thee in the way which thou shalt go: I will guide thee with mine eye.", reference: "Psalm 32:8", devotional: "God promises personal guidance and counsel. He watches over you with loving attention and directs your path. You don't have to figure out life on your own.", prayer: "Lord, instruct me and teach me the way I should go. Guide me with Your loving counsel today. Amen.", date: "" },
  { id: "48", verse: "But my God shall supply all your need according to his riches in glory by Christ Jesus.", reference: "Philippians 4:19", devotional: "God's provision is not limited by earthly resources. He supplies from the riches of His glory, which are infinite. Trust that He will meet every need in your life.", prayer: "Father, I trust You to meet all my needs according to Your glorious riches in Christ Jesus. Amen.", date: "" },
  { id: "49", verse: "Commit thy way unto the Lord; trust also in him; and he shall bring it to pass. And he shall bring forth thy righteousness as the light, and thy judgment as the noonday.", reference: "Psalm 37:5-6", devotional: "When you commit your plans and dreams to God, He works on your behalf. Your faithfulness will be vindicated. Trust the process and let God bring your reward in His time.", prayer: "Lord, I commit my way to You. I trust You to bring about Your purposes in my life. Amen.", date: "" },
  { id: "50", verse: "Heal me, O Lord, and I shall be healed; save me, and I shall be saved: for thou art my praise.", reference: "Jeremiah 17:14", devotional: "God is the ultimate healer of body, mind, and spirit. When He heals, the healing is complete and lasting. Bring your wounds to Him and trust in His restoring power.", prayer: "Lord, heal me and I will be truly healed. Save me and I will be saved. You alone are worthy of my praise. Amen.", date: "" },
  { id: "51", verse: "For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind.", reference: "2 Timothy 1:7", devotional: "God has not given you a spirit of fear. His Spirit within you is one of power, love, and a sound mind. Walk boldly in the confidence that His Spirit empowers you.", prayer: "Father, thank You for giving me a spirit of power, love, and self-discipline. Drive out every fear from my heart. Amen.", date: "" },
  { id: "52", verse: "Finally, my brethren, be strong in the Lord, and in the power of his might.", reference: "Ephesians 6:10", devotional: "Your strength for spiritual battles comes from the Lord. His mighty power is available to you through faith. Stand firm and be strengthened by His unlimited resources.", prayer: "Lord, I choose to be strong in You and in Your mighty power. Equip me for every challenge ahead. Amen.", date: "" },
  { id: "53", verse: "Wait on the Lord: be of good courage, and he shall strengthen thine heart: wait, I say, on the Lord.", reference: "Psalm 27:14", devotional: "Waiting on God requires both strength and courage. It is not passive but an active trust in His perfect timing. Be strong, take heart, and know that He will come through.", prayer: "Lord, give me the strength to wait on You. Fill my heart with courage as I trust in Your timing. Amen.", date: "" },
  { id: "54", verse: "Every good gift and every perfect gift is from above, and cometh down from the Father of lights, with whom is no variableness, neither shadow of turning.", reference: "James 1:17", devotional: "Every blessing in your life comes from God's generous hand. He is unchanging and completely good. His gifts are perfect and His character is constant.", prayer: "Father of lights, thank You for every good gift in my life. You never change and Your goodness is constant. Amen.", date: "" },
  { id: "55", verse: "Now the God of hope fill you with all joy and peace in believing, that ye may abound in hope, through the power of the Holy Ghost.", reference: "Romans 15:13", devotional: "God is the source of all hope. As you trust Him, He fills you with supernatural joy and peace. His Spirit causes hope to overflow from your life into the lives of others.", prayer: "God of hope, fill me with joy and peace. Let hope overflow in my life by the power of Your Holy Spirit. Amen.", date: "" },
  { id: "56", verse: "But thou, O Lord, art a shield for me; my glory, and the lifter up of mine head.", reference: "Psalm 3:3", devotional: "When shame and defeat try to weigh you down, God lifts your head. He surrounds you like a shield and restores your dignity. In Him, you can hold your head high.", prayer: "Lord, be my shield today. Lift my head above discouragement and shame. You are my glory and my defender. Amen.", date: "" },
  { id: "57", verse: "It is of the Lord's mercies that we are not consumed, because his compassions fail not. They are new every morning: great is thy faithfulness.", reference: "Lamentations 3:22-23", devotional: "Each new day brings fresh mercies from God. His love is unwavering and His faithfulness is great. No matter what yesterday held, today is filled with new grace.", prayer: "Lord, thank You for Your mercies that are new every morning. Great is Your faithfulness to me. Amen.", date: "" },
  { id: "58", verse: "Peace I leave with you, my peace I give unto you: not as the world giveth, give I unto you. Let not your heart be troubled, neither let it be afraid.", reference: "John 14:27", devotional: "The peace Jesus offers is unlike anything the world can provide. It is deep, lasting, and available in every circumstance. Receive His gift of peace and let go of fear.", prayer: "Jesus, I receive Your peace today. Calm my troubled heart and remove all fear. Your peace is my anchor. Amen.", date: "" },
  { id: "59", verse: "Behold, I will do a new thing; now it shall spring forth; shall ye not know it? I will even make a way in the wilderness, and rivers in the desert.", reference: "Isaiah 43:19", devotional: "God specializes in new beginnings. Even in the wilderness seasons of life, He is making a way. Open your eyes to see what He is doing and trust that new beginnings are ahead.", prayer: "Lord, I trust You to do a new thing in my life. Make a way where there seems to be no way. Amen.", date: "" },
  { id: "60", verse: "And be ye kind one to another, tenderhearted, forgiving one another, even as God for Christ's sake hath forgiven you.", reference: "Ephesians 4:32", devotional: "Kindness, compassion, and forgiveness are the marks of Christ's followers. Because God has forgiven you so much, you can extend that same grace to others.", prayer: "Father, help me to be kind, compassionate, and forgiving. Let Your grace flow through me to everyone I encounter. Amen.", date: "" },
  { id: "61", verse: "But the Lord is faithful, who shall stablish you, and keep you from evil.", reference: "2 Thessalonians 3:3", devotional: "God's faithfulness is your guarantee of protection. He strengthens you against every attack and shields you from the enemy. Stand confident in His faithful care.", prayer: "Lord, thank You for Your faithfulness. Strengthen me and protect me from every scheme of the enemy. Amen.", date: "" },
  { id: "62", verse: "This is the day which the Lord hath made; we will rejoice and be glad in it.", reference: "Psalm 118:24", devotional: "Every day is a gift from God, crafted by His hand for your good. Choose joy and gladness today, not because circumstances are perfect, but because God is good.", prayer: "Lord, thank You for this day You have made. I choose to rejoice and be glad in it. Fill me with Your joy. Amen.", date: "" },
  { id: "63", verse: "Now faith is the substance of things hoped for, the evidence of things not seen.", reference: "Hebrews 11:1", devotional: "Faith is the substance of your hopes made real and the evidence of God's promises yet unseen. It is the confident trust that what God has spoken will come to pass.", prayer: "Lord, increase my faith. Give me confidence in Your promises and assurance of Your unseen work in my life. Amen.", date: "" },
  { id: "64", verse: "Be strong and of a good courage, fear not, nor be afraid of them: for the Lord thy God, he it is that doth go with thee; he will not fail thee, nor forsake thee.", reference: "Deuteronomy 31:6", devotional: "God's command to be courageous is rooted in His unfailing promise to never leave you. His presence goes before you, behind you, and beside you in every situation.", prayer: "God, I receive Your command to be strong and courageous. Thank You for being with me wherever I go. Amen.", date: "" },
  { id: "65", verse: "Hear, O Israel: The Lord our God is one Lord.", reference: "Deuteronomy 6:4", devotional: "This foundational declaration reminds us that our God is one, supreme and indivisible. In a world of many distractions and competing loyalties, the Lord alone is God. Let this truth anchor your worship.", prayer: "Lord, You alone are God. I declare my allegiance to You and You only. Help me to worship You with undivided devotion. Amen.", date: "" },
  { id: "66", verse: "I will praise thee; for I am fearfully and wonderfully made: marvellous are thy works; and that my soul knoweth right well.", reference: "Psalm 139:14", devotional: "You are God's masterpiece, carefully and wonderfully created. Every detail of your being was designed with purpose and love. Embrace who God made you to be.", prayer: "Lord, thank You for making me fearfully and wonderfully. Help me to see myself as Your beautiful creation. Amen.", date: "" },
  { id: "67", verse: "My brethren, count it all joy when ye fall into divers temptations; knowing this, that the trying of your faith worketh patience.", reference: "James 1:2-3", devotional: "Trials are not punishments but opportunities for growth. When your faith is tested, perseverance is produced. Each challenge strengthens your spiritual muscles and deepens your trust in God.", prayer: "Lord, help me to find joy even in trials. Use every challenge to build perseverance and deepen my faith. Amen.", date: "" },
  { id: "68", verse: "For with God nothing shall be impossible.", reference: "Luke 1:37", devotional: "The God you serve has no limitations. What seems impossible to you is completely possible for Him. Bring your impossible situations to the God who specializes in miracles.", prayer: "Father, I believe that nothing is impossible with You. I bring my impossible situations to Your throne of grace. Amen.", date: "" },
  { id: "69", verse: "Let all your things be done with charity.", reference: "1 Corinthians 16:14", devotional: "Love should be the motivation behind every action, word, and thought. When love drives your life, everything changes. Let God's love be the foundation of all you do.", prayer: "Lord, help me to do everything in love. Let Your love be my motivation in every situation. Amen.", date: "" },
  { id: "70", verse: "If we confess our sins, he is faithful and just to forgive us our sins, and to cleanse us from all unrighteousness.", reference: "1 John 1:9", devotional: "God's forgiveness is always available when you come to Him honestly. He is faithful to cleanse and restore you. Don't carry the burden of guilt when grace is freely offered.", prayer: "Lord, I confess my sins to You. Thank You for Your faithful forgiveness. Cleanse me and make me new. Amen.", date: "" },
  { id: "71", verse: "The Lord will give strength unto his people; the Lord will bless his people with peace.", reference: "Psalm 29:11", devotional: "God is the source of both strength and peace. He doesn't just give you the power to endure; He also gives you the peace to rest. His blessings are complete and perfect.", prayer: "Lord, give me Your strength and bless me with Your peace. Sustain me with Your power and calm me with Your presence. Amen.", date: "" },
  { id: "72", verse: "He that dwelleth in the secret place of the most High shall abide under the shadow of the Almighty.", reference: "Psalm 91:1", devotional: "When you make God your dwelling place, you find rest under His mighty shadow. His shelter is the safest place in the universe. Abide in Him and experience His protection.", prayer: "Most High God, I dwell in Your shelter. Cover me with Your shadow and give me rest in Your presence. Amen.", date: "" },
  { id: "73", verse: "For we are his workmanship, created in Christ Jesus unto good works, which God hath before ordained that we should walk in them.", reference: "Ephesians 2:10", devotional: "You are God's masterpiece with a purpose already prepared for you. He has designed good works for you to walk in. Your life has meaning and your work has eternal significance.", prayer: "Father, thank You for creating me as Your handiwork. Lead me into the good works You have prepared for me. Amen.", date: "" },
  { id: "74", verse: "He hath made every thing beautiful in his time: also he hath set the world in their heart, so that no man can find out the work that God maketh from the beginning to the end.", reference: "Ecclesiastes 3:11", devotional: "God's timing is perfect, and He makes all things beautiful in their season. The longing in your heart for something more is the echo of eternity that God has placed within you.", prayer: "Lord, help me to trust Your timing. Make everything in my life beautiful in its season. Fill my heart with eternal purpose. Amen.", date: "" },
  { id: "75", verse: "O give thanks unto the Lord, for he is good: for his mercy endureth for ever.", reference: "Psalm 107:1", devotional: "Gratitude is the natural response to God's goodness. His love is not temporary but endures through every season of life. Let thanksgiving overflow from your heart today.", prayer: "Lord, I give You thanks for You are good. Your love endures forever. Fill my heart with gratitude. Amen.", date: "" },
  { id: "76", verse: "I am the vine, ye are the branches: He that abideth in me, and I in him, the same bringeth forth much fruit: for without me ye can do nothing.", reference: "John 15:5", devotional: "Fruitfulness comes from staying connected to Jesus. Just as a branch cannot bear fruit on its own, you need His life flowing through you. Abide in Him and watch your life flourish.", prayer: "Jesus, I choose to remain in You. Apart from You I can do nothing. Flow through me and produce much fruit. Amen.", date: "" },
  { id: "77", verse: "And let us not be weary in well doing: for in due season we shall reap, if we faint not.", reference: "Galatians 6:9", devotional: "Don't grow tired of doing what is right. God promises a harvest for those who persevere. Your faithfulness is never wasted, even when you don't see immediate results.", prayer: "Lord, give me endurance to keep doing good. Help me not to grow weary but to trust that a harvest is coming. Amen.", date: "" },
  { id: "78", verse: "The Lord is good, a strong hold in the day of trouble; and he knoweth them that trust in him.", reference: "Nahum 1:7", devotional: "God's goodness is your refuge when trouble surrounds you. He personally cares for those who put their trust in Him. You are not forgotten or overlooked.", prayer: "Lord, You are good and You are my refuge. Thank You for caring for me in times of trouble. Amen.", date: "" },
  { id: "79", verse: "Draw nigh to God, and he will draw nigh to you.", reference: "James 4:8", devotional: "God responds to your seeking heart. When you take a step toward Him, He rushes toward you. The intimacy you desire with God begins with your willingness to draw close.", prayer: "Lord, I draw near to You today. Meet me in this moment and draw near to me. I long for Your presence. Amen.", date: "" },
  { id: "80", verse: "O taste and see that the Lord is good: blessed is the man that trusteth in him.", reference: "Psalm 34:8", devotional: "God's goodness is not just something to know about; it is something to experience personally. Take refuge in Him and discover for yourself how good He truly is.", prayer: "Lord, let me taste and see Your goodness. I take refuge in You and trust in Your unfailing love. Amen.", date: "" },
  { id: "81", verse: "Teach me to do thy will; for thou art my God: thy spirit is good; lead me into the land of uprightness.", reference: "Psalm 143:10", devotional: "A teachable heart is precious to God. When you ask Him to teach you His will, His Spirit leads you on a steady, sure path. Submit to His teaching and walk in His ways.", prayer: "Lord, teach me to do Your will. Let Your good Spirit lead me on level ground today. Amen.", date: "" },
  { id: "82", verse: "While we look not at the things which are seen, but at the things which are not seen: for the things which are seen are temporal; but the things which are not seen are eternal.", reference: "2 Corinthians 4:18", devotional: "The visible things of this world are passing away, but the unseen realities of God's kingdom are eternal. Set your focus on what truly lasts and live with an eternal perspective.", prayer: "Lord, fix my eyes on the eternal and unseen. Help me to live with an eternal perspective in all I do. Amen.", date: "" },
  { id: "83", verse: "As for God, his way is perfect: the word of the Lord is tried: he is a buckler to all those that trust in him.", reference: "Psalm 18:30", devotional: "God's ways are never wrong, and His Word is never flawed. When you take refuge in Him, His perfect protection covers you completely. Trust His perfect plan for your life.", prayer: "Lord, Your way is perfect and Your Word is flawless. I take refuge in You and trust Your perfect plan. Amen.", date: "" },
  { id: "84", verse: "Humble yourselves in the sight of the Lord, and he shall lift you up.", reference: "James 4:10", devotional: "Humility before God is the pathway to being lifted up. When you lower yourself in His presence, He raises you up with honor. God exalts the humble and gives grace to the meek.", prayer: "Lord, I humble myself before You. Lift me up in Your time and in Your way. I submit to Your lordship. Amen.", date: "" },
  { id: "85", verse: "The fear of the Lord is the beginning of wisdom: and the knowledge of the holy is understanding.", reference: "Proverbs 9:10", devotional: "True wisdom begins with reverence for God. When you honor Him above all else, understanding follows. Seek to know Him deeply and wisdom will guide every area of your life.", prayer: "Lord, teach me to fear You rightly. Grant me wisdom and understanding as I seek to know You more. Amen.", date: "" },
  { id: "86", verse: "Greater love hath no man than this, that a man lay down his life for his friends.", reference: "John 15:13", devotional: "The greatest love is sacrificial love. Jesus demonstrated this perfectly on the cross. His example calls us to love selflessly, putting others before ourselves.", prayer: "Jesus, thank You for laying down Your life for me. Teach me to love sacrificially as You have loved me. Amen.", date: "" },
  { id: "87", verse: "Wherefore comfort yourselves together, and edify one another, even as also ye do.", reference: "1 Thessalonians 5:11", devotional: "We are called to be encouragers and builders in the lives of others. Your words have the power to lift someone's spirit and strengthen their faith. Speak life today.", prayer: "Lord, use me to encourage and build up others today. Let my words bring life and hope to those around me. Amen.", date: "" },
  { id: "88", verse: "Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you.", reference: "Matthew 7:7", devotional: "God invites you to ask, seek, and knock with bold confidence. He is a generous Father who delights in giving good gifts to His children. Approach Him with faith and expectation.", prayer: "Father, I come boldly asking, seeking, and knocking. Open the doors You have for me and give generously. Amen.", date: "" },
  { id: "89", verse: "And now abideth faith, hope, charity, these three; but the greatest of these is charity.", reference: "1 Corinthians 13:13", devotional: "Faith, hope, and love are the enduring pillars of the Christian life. Among them, love stands supreme because it reflects God's very nature. Let love be your highest pursuit.", prayer: "Lord, let faith, hope, and love define my life. Above all, help me to love as You love. Amen.", date: "" },
  { id: "90", verse: "They looked unto him, and were lightened: and their faces were not ashamed.", reference: "Psalm 34:5", devotional: "When you turn your eyes to God, His glory transforms you from the inside out. Shame has no place in the lives of those who gaze upon Him. Look to Him and be radiant.", prayer: "Lord, I look to You today. Let Your radiance shine through me. Remove all shame and fill me with Your glory. Amen.", date: "" },
  { id: "91", verse: "He shall cover thee with his feathers, and under his wings shalt thou trust: his truth shall be thy shield and buckler.", reference: "Psalm 91:4", devotional: "God's protection is intimate and complete. Like a mother bird sheltering her young, He covers you with His love. His faithfulness is a shield that never fails.", prayer: "Lord, cover me under Your wings. Let Your faithfulness be my shield. I find refuge in Your tender care. Amen.", date: "" },
  { id: "92", verse: "Set your affection on things above, not on things on the earth.", reference: "Colossians 3:2", devotional: "Where you focus your mind determines the direction of your life. Setting your thoughts on heavenly realities transforms your perspective and frees you from the grip of worldly concerns.", prayer: "Lord, help me to set my mind on things above. Lift my thoughts from earthly worries to heavenly truth. Amen.", date: "" },
  { id: "93", verse: "And we have known and believed the love that God hath to us. God is love; and he that dwelleth in love dwelleth in God, and God in him.", reference: "1 John 4:16", devotional: "Love is not just something God does; it is who He is. When you live in love, you live in God Himself. Let love define your every relationship and action.", prayer: "Lord, You are love. Help me to live in love so that I live in You. Let Your love flow through me to others. Amen.", date: "" },
  { id: "94", verse: "Behold, what manner of love the Father hath bestowed upon us, that we should be called the sons of God: therefore the world knoweth us not, because it knew him not.", reference: "1 John 3:1", devotional: "God's love for you is not stingy but lavish. He has given you the highest honor: to be called His child. Rest in the security and identity that comes from being God's beloved.", prayer: "Father, thank You for lavishing Your love on me. I am Your child, and that is my greatest identity. Amen.", date: "" },
  { id: "95", verse: "The Lord is merciful and gracious, slow to anger, and plenteous in mercy.", reference: "Psalm 103:8", devotional: "God's compassion and grace are abundant. He is patient with your struggles and overflowing with love for you. His character is consistently good, even when you fall short.", prayer: "Lord, thank You for Your compassion and grace. You are slow to anger and abounding in love toward me. Amen.", date: "" },
  { id: "96", verse: "For by grace are ye saved through faith; and that not of yourselves: it is the gift of God: not of works, lest any man should boast.", reference: "Ephesians 2:8-9", devotional: "Salvation cannot be earned by good deeds or religious effort. It is purely a gift of God's grace, received through faith. This removes all room for boasting and leaves only room for gratitude.", prayer: "Father, thank You for saving me by grace through faith. I boast only in Your goodness and generosity. Amen.", date: "" },
  { id: "97", verse: "I will lift up mine eyes unto the hills, from whence cometh my help. My help cometh from the Lord, which made heaven and earth.", reference: "Psalm 100:4", devotional: "The way into God's presence is through a thankful and praising heart. Gratitude opens doors that worry keeps closed. Come before Him today with praise on your lips.", prayer: "Lord, I enter Your gates with thanksgiving and Your courts with praise. I give thanks for Your goodness. Amen.", date: "" },
  { id: "98", verse: "And be not conformed to this world: but be ye transformed by the renewing of your mind, that ye may prove what is that good, and acceptable, and perfect, will of God.", reference: "Zechariah 4:6", devotional: "Human strength and ability have limits, but God's Spirit has none. The breakthroughs you need won't come through your own power but through the unlimited power of the Holy Spirit.", prayer: "Lord, I rely not on my own might or power but on Your Spirit. Let Your Spirit accomplish what I cannot. Amen.", date: "" },
  { id: "99", verse: "Yea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff they comfort me.", reference: "Romans 5:8", devotional: "God didn't wait for you to be perfect before loving you. He loved you at your worst and gave His best. This is the depth and wonder of His unconditional love.", prayer: "Lord, thank You for loving me while I was still a sinner. Your love is unconditional and undeserved. I am grateful. Amen.", date: "" },
  { id: "100", verse: "There hath no temptation taken you but such as is common to man: but God is faithful, who will not suffer you to be tempted above that ye are able; but will with the temptation also make a way to escape, that ye may be able to bear it.", reference: "Psalm 19:1", devotional: "All of creation speaks of God's magnificence. The stars, the sunsets, the mountains, and the seas testify to His creative power. Take time today to see His glory in the world around you.", prayer: "Lord, open my eyes to see Your glory declared in creation. The heavens proclaim Your handiwork. I stand in awe. Amen.", date: "" },
  { id: "101", verse: "Surely goodness and mercy shall follow me all the days of my life: and I will dwell in the house of the Lord for ever.", reference: "Psalm 147:3", devotional: "God is the great physician of wounded hearts. He tenderly binds up your emotional and spiritual wounds. No hurt is too deep for His healing touch. Bring your pain to Him.", prayer: "Lord, heal my broken heart and bind up my wounds. Your healing touch makes all things whole. Amen.", date: "" },
  { id: "102", verse: "Let your conversation be without covetousness; and be content with such things as ye have: for he hath said, I will never leave thee, nor forsake thee.", reference: "Romans 8:38-39", devotional: "Nothing in all creation has the power to separate you from God's love. Not your past, not your present, not your future. His love in Christ is absolutely unbreakable and eternal.", prayer: "Lord, thank You that nothing can separate me from Your love. I rest secure in the unbreakable love of Christ. Amen.", date: "" },
  { id: "103", verse: "Cast thy burden upon the Lord, and he shall sustain thee: he shall never suffer the righteous to be moved.", reference: "Psalm 143:8", devotional: "Begin each morning seeking God's unfailing love and direction. When you entrust your day to Him, He reveals the path you should take. Start your day in His presence.", prayer: "Lord, let the morning bring word of Your unfailing love. Show me the way I should go today. I entrust my life to You. Amen.", date: "" },
  { id: "104", verse: "Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.", reference: "Deuteronomy 20:4", devotional: "God fights alongside you in every battle. He is not a distant observer but an active warrior on your behalf. Victory is assured because He is with you.", prayer: "Lord, fight for me against my enemies. You are my mighty warrior and You give me victory. I trust in Your strength. Amen.", date: "" },
  { id: "105", verse: "That if thou shalt confess with thy mouth the Lord Jesus, and shalt believe in thine heart that God hath raised him from the dead, thou shalt be saved.", reference: "Isaiah 58:11", devotional: "Even in the driest seasons of life, God promises to guide and sustain you. He satisfies your deepest needs and strengthens you from the inside out. Trust His constant provision.", prayer: "Lord, guide me always. Satisfy my needs even in dry seasons and strengthen my frame. You are my constant provision. Amen.", date: "" },
  { id: "106", verse: "Truly my soul waiteth upon God: from him cometh my salvation. He only is my rock and my salvation; he is my defence; I shall not be greatly moved.", reference: "Psalm 145:18", devotional: "God is not far away when you call out to Him. He draws near to those who seek Him with sincere hearts. Your honest prayer reaches His ears immediately.", prayer: "Lord, I call on You in truth. Draw near to me as I seek Your face. You are closer than I realize. Amen.", date: "" },
  { id: "107", verse: "And ye shall know the truth, and the truth shall make you free.", reference: "2 Thessalonians 3:16", devotional: "God desires to give you peace in every situation, at all times, and in every way. His peace is not limited to certain circumstances but is available in all of them.", prayer: "Lord of peace, give me Your peace at all times and in every way. Be with me in every moment. Amen.", date: "" },
  { id: "108", verse: "Enter into his gates with thanksgiving, and into his courts with praise: be thankful unto him, and bless his name. For the Lord is good; his mercy is everlasting; and his truth endureth to all generations.", reference: "Hebrews 12:1", devotional: "You are not running the race of faith alone. Those who have gone before cheer you on. Lay aside every weight and sin, and run your unique race with endurance and focus.", prayer: "Lord, help me to throw off everything that hinders me. Give me perseverance to run the race You have set before me. Amen.", date: "" },
  { id: "109", verse: "If my people, which are called by my name, shall humble themselves, and pray, and seek my face, and turn from their wicked ways; then will I hear from heaven, and will forgive their sin, and will heal their land.", reference: "Hebrews 12:2", devotional: "Jesus is both the author and the finisher of your faith journey. Keep your eyes fixed on Him, not on your circumstances. He blazed the trail and will bring you to completion.", prayer: "Jesus, I fix my eyes on You. You are the pioneer and perfecter of my faith. Lead me forward. Amen.", date: "" },
  { id: "110", verse: "The steps of a good man are ordered by the Lord: and he delighteth in his way. Though he fall, he shall not be utterly cast down: for the Lord upholdeth him with his hand.", reference: "Matthew 5:8", devotional: "Purity of heart is the pathway to experiencing God's presence. When your motives and desires are cleansed, your spiritual vision becomes clear. Seek a pure heart before the Lord.", prayer: "Lord, purify my heart. Remove anything that clouds my vision of You. I want to see You clearly. Amen.", date: "" },
  { id: "111", verse: "Train up a child in the way he should go: and when he is old, he will not depart from it.", reference: "Matthew 5:9", devotional: "Those who actively pursue peace reflect God's heart. Being a peacemaker is not passive but requires intentional effort to bring reconciliation and harmony. This is the mark of God's children.", prayer: "Lord, make me a peacemaker. Use me to bring reconciliation and harmony wherever I go. Amen.", date: "" },
  { id: "112", verse: "God is in the midst of her; she shall not be moved: God shall help her, and that right early.", reference: "Matthew 5:6", devotional: "God promises to satisfy those who deeply desire His righteousness. When you hunger for what is right and good, He fills you with His presence and His ways.", prayer: "Lord, give me a deep hunger and thirst for Your righteousness. Fill me with Your goodness and truth. Amen.", date: "" },
  { id: "113", verse: "Wherefore seeing we also are compassed about with so great a cloud of witnesses, let us lay aside every weight, and the sin which doth so easily beset us, and let us run with patience the race that is set before us.", reference: "Colossians 3:15", devotional: "Christ's peace should be the umpire in your heart, making the final call on every decision. Let His peace govern your thoughts, your words, and your actions. Be thankful in all things.", prayer: "Lord, let Your peace rule in my heart. Make me thankful and at peace in every situation. Amen.", date: "" },
  { id: "114", verse: "Looking unto Jesus the author and finisher of our faith; who for the joy that was set before him endured the cross, despising the shame, and is set down at the right hand of the throne of God.", reference: "Ephesians 6:11", devotional: "Spiritual warfare requires spiritual armor. God has provided everything you need to stand against the enemy's attacks. Put on His armor daily through prayer, faith, and His Word.", prayer: "Lord, help me to put on Your full armor today. Equip me to stand firm against every scheme of the enemy. Amen.", date: "" },
  { id: "115", verse: "Let the words of my mouth, and the meditation of my heart, be acceptable in thy sight, O Lord, my strength, and my redeemer.", reference: "Romans 14:17", devotional: "God's kingdom is not about outward rituals but inward realities. Righteousness, peace, and joy in the Holy Spirit are the marks of His kingdom in your life.", prayer: "Lord, let Your kingdom of righteousness, peace, and joy reign in my heart through the Holy Spirit. Amen.", date: "" },
  { id: "116", verse: "Keep thy heart with all diligence; for out of it are the issues of life.", reference: "Psalm 34:4", devotional: "When you seek God earnestly, He responds with deliverance. Every fear that grips your heart can be broken by His power. Seek Him and experience freedom from fear.", prayer: "Lord, I seek You with all my heart. Answer me and deliver me from all my fears. Set me free. Amen.", date: "" },
  { id: "117", verse: "Bless the Lord, O my soul: and all that is within me, bless his holy name. Bless the Lord, O my soul, and forget not all his benefits.", reference: "Isaiah 40:29", devotional: "When your energy is depleted and your strength is gone, God offers supernatural renewal. He doesn't just maintain your strength; He increases it. Come to Him in your weakness.", prayer: "Lord, give me strength in my weariness. Increase my power when I am weak. You are my source of energy and life. Amen.", date: "" },
  { id: "118", verse: "Ye are of God, little children, and have overcome them: because greater is he that is in you, than he that is in the world.", reference: "Psalm 145:3", devotional: "God's greatness is beyond human comprehension. No matter how much you learn about Him, there is always more to discover. He is infinitely great and worthy of your highest praise.", prayer: "Lord, You are great and most worthy of praise. Your greatness is unfathomable. I worship You with all my heart. Amen.", date: "" },
  { id: "119", verse: "I will say of the Lord, He is my refuge and my fortress: my God; in him will I trust.", reference: "Psalm 145:9", devotional: "God's goodness extends to every person and every part of His creation. His compassion knows no bounds. Rest in the truth that His goodness is directed toward you.", prayer: "Lord, thank You for Your goodness and compassion. You are good to all, and I rest in Your loving care. Amen.", date: "" },
  { id: "120", verse: "Teaching them to observe all things whatsoever I have commanded you: and, lo, I am with you alway, even unto the end of the world. Amen.", reference: "Psalm 121:1-2", devotional: "When you look for help, look up. Your help comes from the Creator of everything. The One who made the mountains can certainly move the ones standing in your way.", prayer: "Lord, my help comes from You, the Maker of heaven and earth. I lift my eyes to You in every need. Amen.", date: "" },
  { id: "121", verse: "Thou wilt shew me the path of life: in thy presence is fulness of joy; at thy right hand there are pleasures for evermore.", reference: "Matthew 19:26", devotional: "What is impossible by human standards is completely possible for God. Your limitations are not His limitations. Bring your impossible situations to the One for whom nothing is too hard.", prayer: "Lord, I believe that with You all things are possible. Transform my impossibilities into testimonies of Your power. Amen.", date: "" },
  { id: "122", verse: "For I the Lord thy God will hold thy right hand, saying unto thee, Fear not; I will help thee.", reference: "Psalm 121:5", devotional: "God personally watches over you and protects you from harm. He is as close as your own shadow, providing shelter and security. You are always under His watchful care.", prayer: "Lord, You are my keeper. Cover me with Your protection and shade me from harm. I am safe in Your care. Amen.", date: "" },
  { id: "123", verse: "As far as the east is from the west, so far hath he removed our transgressions from us.", reference: "Proverbs 3:6", devotional: "When you include God in every area of your life, He takes responsibility for guiding your direction. Acknowledge Him in your decisions, relationships, and work, and He will lead you well.", prayer: "Lord, I acknowledge You in all my ways. Direct my paths and lead me in Your perfect will. Amen.", date: "" },
  { id: "124", verse: "And whatsoever ye do, do it heartily, as to the Lord, and not unto men.", reference: "Psalm 121:5-6", devotional: "God's protection is constant, day and night. He guards you from every form of harm, both seen and unseen. His watchful eye never closes, and His care never ceases.", prayer: "Lord, watch over me day and night. Protect me from every harm. Your constant care is my comfort. Amen.", date: "" },
  { id: "125", verse: "Rest in the Lord, and wait patiently for him: fret not thyself because of him who prospereth in his way, because of the man who bringeth wicked devices to pass.", reference: "Joel 2:28", devotional: "God promises to pour out His Spirit generously on all people. This outpouring brings prophetic insight, dreams, and visions. The Holy Spirit is available to everyone who seeks Him.", prayer: "Lord, pour out Your Spirit upon me. Let me experience Your prophetic power and walk in the vision You give. Amen.", date: "" },
  { id: "126", verse: "Rejoicing in hope; patient in tribulation; continuing instant in prayer.", reference: "Romans 12:12", devotional: "These three postures define the Christian life: joyful hope, patient endurance, and faithful prayer. Together they form a balanced approach to life's ups and downs.", prayer: "Lord, help me to be joyful in hope, patient in affliction, and faithful in prayer. Balance my life with these qualities. Amen.", date: "" },
  { id: "127", verse: "Search me, O God, and know my heart: try me, and know my thoughts: and see if there be any wicked way in me, and lead me in the way everlasting.", reference: "Deuteronomy 16:15", devotional: "God's blessing extends to every area of your labor. He desires to make your joy complete by prospering the work of your hands. Work with excellence and trust Him for the harvest.", prayer: "Lord, bless the work of my hands. Let Your favor rest upon my labor and make my joy complete. Amen.", date: "" },
  { id: "128", verse: "Thou wilt keep him in perfect peace, whose mind is stayed on thee: because he trusteth in thee.", reference: "Ephesians 4:4", devotional: "The unity of the church reflects the unity of God's Spirit. One body, one Spirit, one hope — these bind believers together across every divide. Celebrate the unity you share in Christ.", prayer: "Lord, help me to cherish the unity of Your body. May we be one as You are one. Amen.", date: "" },
  { id: "129", verse: "Trust in the Lord, and do good; so shalt thou dwell in the land, and verily thou shalt be fed.", reference: "Ephesians 3:20", devotional: "God's ability exceeds your wildest imagination. He can do more than you can ask or even think of. His power at work within you makes the extraordinary possible.", prayer: "Lord, I believe You can do immeasurably more than all I ask or imagine. Let Your power work within me. Amen.", date: "" },
  { id: "130", verse: "Ye are the light of the world. A city that is set on an hill cannot be hid.", reference: "Proverbs 17:22", devotional: "Joy is healing for the soul. A cheerful heart brings life and vitality, while despair drains your strength. Choose joy today and let God's gladness be your medicine.", prayer: "Lord, give me a cheerful heart. Let Your joy be the medicine that heals and restores me from the inside out. Amen.", date: "" },
  { id: "131", verse: "I waited patiently for the Lord; and he inclined unto me, and heard my cry. He brought me up also out of an horrible pit, out of the miry clay, and set my feet upon a rock, and established my goings.", reference: "Psalm 139:17", devotional: "God thinks about you constantly. His thoughts toward you are precious and countless, more than the grains of sand. You are always on His mind and in His heart.", prayer: "Lord, how precious are Your thoughts toward me. Help me to meditate on Your love and care throughout this day. Amen.", date: "" },
  { id: "132", verse: "Let not mercy and truth forsake thee: bind them about thy neck; write them upon the table of thine heart: so shalt thou find favour and good understanding in the sight of God and man.", reference: "Isaiah 40:25", devotional: "God is beyond comparison. No one and nothing can be placed alongside Him. His holiness, power, and love are in a category all their own. He stands alone in His majesty.", prayer: "Lord, You are incomparable. No one is like You. I worship You in the uniqueness of Your holiness. Amen.", date: "" },
  { id: "133", verse: "He healeth the broken in heart, and bindeth up their wounds.", reference: "Psalm 133:1", devotional: "Unity among believers is both beautiful and powerful. When God's people live in harmony, His blessing flows freely. Pursue unity and peace in your relationships with fellow believers.", prayer: "Lord, help me to be a source of unity among Your people. Let peace and harmony characterize my relationships. Amen.", date: "" },
  { id: "134", verse: "But God commendeth his love toward us, in that, while we were yet sinners, Christ died for us.", reference: "Galatians 2:20", devotional: "The Christian life is Christ living through you. Your old self has been crucified and a new life has begun. Live each day by faith in the Son of God who loved you and died for you.", prayer: "Lord, let Christ live through me today. I surrender my life to You and live by faith in Your Son. Amen.", date: "" },
  { id: "135", verse: "So teach us to number our days, that we may apply our hearts unto wisdom.", reference: "Psalm 34:17", devotional: "When you cry out to God, He hears you. Every prayer, every plea, every whispered word reaches His ears. He is a deliverer who rescues you from all your troubles.", prayer: "Lord, hear my cry today. Deliver me from all my troubles. I trust in Your attentive ear and mighty hand. Amen.", date: "" },
  { id: "136", verse: "For my thoughts are not your thoughts, neither are your ways my ways, saith the Lord. For as the heavens are higher than the earth, so are my ways higher than your ways, and my thoughts than your thoughts.", reference: "Matthew 6:21", devotional: "What you value most reveals the condition of your heart. When your greatest treasure is God and His kingdom, your heart is aligned with eternal purposes.", prayer: "Lord, let my greatest treasure be You. Align my heart with Your kingdom and Your eternal purposes. Amen.", date: "" },
  { id: "137", verse: "For the word of the Lord is right; and all his works are done in truth.", reference: "Romans 8:1", devotional: "If you are in Christ, condemnation has no legal claim on you. The verdict has been declared: not guilty. Walk in the freedom of this truth and refuse to live under false guilt.", prayer: "Lord, thank You that there is no condemnation for me in Christ Jesus. I walk in freedom from guilt and shame. Amen.", date: "" },
  { id: "138", verse: "In the beginning was the Word, and the Word was with God, and the Word was God.", reference: "Psalm 34:19", devotional: "Being righteous doesn't exempt you from trouble, but it guarantees God's deliverance. He is faithful to rescue you from every difficulty. Hold on to His promise of deliverance.", prayer: "Lord, deliver me from all my troubles. I trust that Your deliverance is sure and Your faithfulness is unwavering. Amen.", date: "" },
  { id: "139", verse: "For the Lord God is a sun and shield: the Lord will give grace and glory: no good thing will he withhold from them that walk uprightly.", reference: "Matthew 5:14", devotional: "Jesus calls you the light of the world. Your life is meant to shine brightly, pointing others to God. Don't hide your faith; let it illuminate the darkness around you.", prayer: "Lord, let my light shine before others. Use my life to bring glory to Your name and hope to those in darkness. Amen.", date: "" },
  { id: "140", verse: "Commit thy works unto the Lord, and thy thoughts shall be established.", reference: "Psalm 24:1", devotional: "Everything belongs to God. He is the rightful owner of all creation. When you understand this, you become a faithful steward rather than an anxious owner of the things in your life.", prayer: "Lord, everything I have belongs to You. Help me to be a faithful steward of all You have entrusted to me. Amen.", date: "" },
  { id: "141", verse: "The young lions do lack, and suffer hunger: but they that seek the Lord shall not want any good thing.", reference: "Colossians 3:12", devotional: "As God's beloved children, you are called to wear His character daily. Compassion, kindness, humility, gentleness, and patience are the garments of a Christ-follower.", prayer: "Lord, help me to clothe myself with compassion, kindness, humility, gentleness, and patience every day. Amen.", date: "" },
  { id: "142", verse: "Therefore I say unto you, What things soever ye desire, when ye pray, believe that ye receive them, and ye shall have them.", reference: "Psalm 23:6", devotional: "God's goodness and mercy are not things you have to chase; they chase after you. Every day of your life, His blessings pursue you. And your eternal home is secure in His presence.", prayer: "Lord, thank You that Your goodness and mercy follow me every day. I will dwell in Your house forever. Amen.", date: "" },
  { id: "143", verse: "But let all those that put their trust in thee rejoice: let them ever shout for joy, because thou defendest them: let them also that love thy name be joyful in thee. For thou, Lord, wilt bless the righteous; with favour wilt thou compass him as with a shield.", reference: "Philippians 4:4", devotional: "Joy in the Lord is not dependent on circumstances. It is a choice and a command. Paul emphasizes this by saying it twice. Choose to rejoice in the Lord today, no matter what.", prayer: "Lord, I choose to rejoice in You today. Fill my heart with Your joy regardless of my circumstances. Amen.", date: "" },
  { id: "144", verse: "For thou, Lord, art good, and ready to forgive; and plenteous in mercy unto all them that call upon thee.", reference: "2 Timothy 4:17", devotional: "Even when others abandon you, the Lord stands by your side. He gives you strength when you have none left. His faithful presence is your constant source of power.", prayer: "Lord, thank You for standing at my side. Give me strength when I am weak. Your presence is my power. Amen.", date: "" },
  { id: "145", verse: "For I am persuaded, that neither death, nor life, nor angels, nor principalities, nor powers, nor things present, nor things to come, nor height, nor depth, nor any other creature, shall be able to separate us from the love of God, which is in Christ Jesus our Lord.", reference: "John 14:1", devotional: "Jesus speaks directly to your troubled heart with words of comfort. He invites you to extend the same trust you have in God the Father to Him. Belief is the antidote to anxiety.", prayer: "Jesus, I believe in You. Calm my troubled heart with Your words of peace and truth. I trust You. Amen.", date: "" },
  { id: "146", verse: "The heavens declare the glory of God; and the firmament sheweth his handywork.", reference: "2 Corinthians 12:9", devotional: "In your weakness, God's power shines brightest. His grace is always enough for whatever you face. When you feel inadequate, that is exactly when His strength is perfected in you.", prayer: "Lord, Your grace is sufficient for me. Let Your power be made perfect in my weakness. I depend on You. Amen.", date: "" },
  { id: "147", verse: "There are many devices in a man's heart; nevertheless the counsel of the Lord, that shall stand.", reference: "Jeremiah 17:7-8", devotional: "Trusting in God makes you like a deeply rooted tree that thrives even in drought. Your source of life is not circumstances but the living water of God's faithfulness.", prayer: "Lord, I trust in You. Plant me by Your living water and let my roots grow deep in Your faithfulness. Amen.", date: "" },
  { id: "148", verse: "The Lord shall preserve thee from all evil: he shall preserve thy soul. The Lord shall preserve thy going out and thy coming in from this time forth, and even for evermore.", reference: "Psalm 126:3", devotional: "Take a moment to remember the great things God has done in your life. His faithfulness in the past is the foundation for joy in the present and hope for the future.", prayer: "Lord, You have done great things for me. Fill me with joy as I remember Your faithfulness. Amen.", date: "" },
  { id: "149", verse: "Take my yoke upon you, and learn of me; for I am meek and lowly in heart: and ye shall find rest unto your souls. For my yoke is easy, and my burden is light.", reference: "Psalm 30:5", devotional: "Seasons of tears are not permanent. Joy is coming. God promises that morning follows the darkest night. Hold on through the pain; rejoicing is on its way.", prayer: "Lord, though I weep now, I trust that joy comes in the morning. Carry me through the night into Your glorious dawn. Amen.", date: "" },
  { id: "150", verse: "Thy mercy, O Lord, is in the heavens; and thy faithfulness reacheth unto the clouds. Thy righteousness is like the great mountains; thy judgments are a great deep: O Lord, thou preservest man and beast.", reference: "Luke 4:18", devotional: "Jesus declared His mission with these words, and as His follower, you carry the same anointing. The Holy Spirit empowers you to bring good news, healing, and freedom to others.", prayer: "Lord, anoint me with Your Spirit. Use me to proclaim good news and bring hope to those in need. Amen.", date: "" },
  { id: "151", verse: "Behold, God is my salvation; I will trust, and not be afraid: for the Lord Jehovah is my strength and my song; he also is become my salvation.", reference: "Micah 6:8", devotional: "God's requirements are beautifully simple: justice, mercy, and humility. These three qualities capture the essence of a life that honors God. Let them guide your daily choices.", prayer: "Lord, help me to act justly, love mercy, and walk humbly with You. Let these qualities define my life. Amen.", date: "" },
  { id: "152", verse: "One thing have I desired of the Lord, that will I seek after; that I may dwell in the house of the Lord all the days of my life, to behold the beauty of the Lord, and to enquire in his temple.", reference: "Psalm 73:26", devotional: "Even when your body and emotions fail you, God remains your strength. He is your eternal portion, the one constant in a world of change. Lean on His unfailing strength.", prayer: "Lord, when my flesh and heart fail, be my strength. You are my portion forever and my unfailing anchor. Amen.", date: "" },
  { id: "153", verse: "The thief cometh not, but for to steal, and to kill, and to destroy: I am come that they might have life, and that they might have it more abundantly.", reference: "Isaiah 43:2", devotional: "God promises to be with you through every overwhelming circumstance. The waters may rise, but they will not overcome you. His presence is your guarantee of safe passage.", prayer: "Lord, be with me through the waters and the rivers of life. They will not sweep over me because You are my God. Amen.", date: "" },
  { id: "154", verse: "O God, thou art my God; early will I seek thee: my soul thirsteth for thee, my flesh longeth for thee in a dry and thirsty land, where no water is.", reference: "Psalm 113:3", devotional: "God deserves praise from dawn to dusk and every moment in between. His name is worthy of honor in every time zone and every circumstance. Let praise fill your entire day.", prayer: "Lord, from sunrise to sunset I will praise Your name. You are worthy of praise at all times. Amen.", date: "" },
  { id: "155", verse: "The liberal soul shall be made fat: and he that watereth shall be watered also himself.", reference: "Psalm 139:23", devotional: "Inviting God to search your heart is an act of courageous honesty. He already knows everything about you, but this prayer invites His cleansing and transformation. Be open before Him.", prayer: "Lord, search my heart and know me completely. Reveal anything that needs to change and transform me from within. Amen.", date: "" },
  { id: "156", verse: "They that sow in tears shall reap in joy.", reference: "Psalm 84:11", devotional: "God is both your light and your protection. He generously gives favor and honor to those who walk uprightly. Trust that He withholds nothing good from you.", prayer: "Lord, be my sun and shield. Bestow Your favor and honor upon me. I trust that You withhold no good thing. Amen.", date: "" },
  { id: "157", verse: "But thanks be to God, which giveth us the victory through our Lord Jesus Christ.", reference: "Matthew 22:37", devotional: "The greatest commandment calls for total love of God with every part of your being. Heart, soul, and mind are all engaged in loving Him. This wholehearted devotion transforms everything.", prayer: "Lord, I love You with all my heart, soul, and mind. Help me to love You more deeply every day. Amen.", date: "" },
  { id: "158", verse: "The Lord will perfect that which concerneth me: thy mercy, O Lord, endureth for ever: forsake not the works of thine own hands.", reference: "Matthew 22:39", devotional: "Loving others as yourself is inseparable from loving God. The way you treat people reflects the depth of your love for Him. Let compassion for others flow from your love for God.", prayer: "Lord, help me to love my neighbor as myself. Let my love for others be a reflection of my love for You. Amen.", date: "" },
  { id: "159", verse: "But Jesus beheld them, and said unto them, With men this is impossible; but with God all things are possible.", reference: "1 Corinthians 16:13", devotional: "The Christian life requires vigilance, firmness, courage, and strength. These are not passive qualities but active choices you make daily. Stand firm and be strong in the Lord.", prayer: "Lord, help me to stand firm in faith, to be courageous and strong. Guard my heart against compromise. Amen.", date: "" },
  { id: "160", verse: "For his anger endureth but a moment; in his favour is life: weeping may endure for a night, but joy cometh in the morning.", reference: "Psalm 23:4", devotional: "The darkest valleys are not walked alone. God's presence is your comfort and His guidance is your security. Fear has no place when the Shepherd walks beside you.", prayer: "Lord, walk with me through the darkest valleys. Your rod and staff comfort me. I fear no evil with You near. Amen.", date: "" },
  { id: "161", verse: "Let us therefore come boldly unto the throne of grace, that we may obtain mercy, and find grace to help in time of need.", reference: "1 Peter 2:9", devotional: "Your identity in Christ is extraordinary. You are chosen, royal, holy, and special to God. Walk in the confidence of who He has made you to be. You belong to Him.", prayer: "Lord, thank You for choosing me and making me part of Your royal priesthood. Help me to live worthy of this calling. Amen.", date: "" },
  { id: "162", verse: "Be merciful unto me, O God, be merciful unto me: for my soul trusteth in thee: yea, in the shadow of thy wings will I make my refuge, until these calamities be overpast.", reference: "Psalm 62:1", devotional: "True rest is found only in God. No earthly comfort can substitute for the peace that comes from resting in His presence. Let your soul find its home in Him alone.", prayer: "Lord, my soul rests in You alone. You are my salvation and my peace. Quiet my heart in Your presence. Amen.", date: "" },
  { id: "163", verse: "Let not your heart be troubled: ye believe in God, believe also in me.", reference: "Nehemiah 8:10", devotional: "God's joy is not dependent on your circumstances. It is a deep, abiding strength that sustains you through every season. Draw from His joy and find renewed strength for today.", prayer: "Lord, let Your joy be my strength. Fill me with a deep, abiding gladness that sustains me in every season. Amen.", date: "" },
  { id: "164", verse: "My flesh and my heart faileth: but God is the strength of my heart, and my portion for ever.", reference: "Romans 12:2", devotional: "God calls you to be different from the world around you. Transformation begins in your mind as you fill it with God's truth. A renewed mind leads to a transformed life.", prayer: "Lord, transform me by renewing my mind. Help me not to conform to this world but to be shaped by Your truth. Amen.", date: "" },
  { id: "165", verse: "For the Lord giveth wisdom: out of his mouth cometh knowledge and understanding.", reference: "Psalm 119:11", devotional: "God's Word stored in your heart is a powerful weapon against temptation. When Scripture fills your mind, it guards your steps and keeps you on the right path.", prayer: "Lord, help me to hide Your Word in my heart. Let Your truth protect me from sin and guide my steps. Amen.", date: "" },
  { id: "166", verse: "Praise ye the Lord. Blessed is the man that feareth the Lord, that delighteth greatly in his commandments.", reference: "Hebrews 13:6", devotional: "With God as your helper, you have nothing to fear from human opposition. No person can ultimately thwart God's purposes for your life. Rest in the safety of His help.", prayer: "Lord, You are my helper. I will not be afraid. No human opposition can overcome Your purposes for me. Amen.", date: "" },
  { id: "167", verse: "For whether we live, we live unto the Lord; and whether we die, we die unto the Lord: whether we live therefore, or die, we are the Lord's.", reference: "1 John 4:7", devotional: "Love is the evidence of knowing God. When you truly love others, it demonstrates that God's life is active in you. Love is both the proof and the practice of your faith.", prayer: "Lord, help me to love others genuinely. Let my love be evidence that I know You and that You live in me. Amen.", date: "" },
  { id: "168", verse: "The Lord is nigh unto all them that call upon him, to all that call upon him in truth.", reference: "Psalm 121:7", devotional: "God's watchful protection covers your entire life. He keeps you from harm and guards your coming and going. Trust His sovereign protection over every detail of your existence.", prayer: "Lord, keep me from all harm. Watch over my life and guard my coming and going. I trust in Your protection. Amen.", date: "" },
  { id: "169", verse: "He giveth power to the faint; and to them that have no might he increaseth strength.", reference: "Proverbs 15:1", devotional: "The power of a gentle response can diffuse the most heated conflict. Choose your words carefully, knowing that gentleness has the power to turn away anger and bring peace.", prayer: "Lord, give me a gentle tongue. Help me to respond with kindness, even in difficult conversations. Amen.", date: "" },
  { id: "170", verse: "As the hart panteth after the water brooks, so panteth my soul after thee, O God.", reference: "Matthew 5:16", devotional: "Your life is a testimony. When your good deeds are motivated by love for God, they point others to Him. Let your light shine so brightly that others see God in you.", prayer: "Lord, let my light shine before others. May my life bring glory to Your name and draw people to You. Amen.", date: "" },
  { id: "171", verse: "And let the peace of God rule in your hearts, to the which also ye are called in one body; and be ye thankful.", reference: "Hebrews 13:5", devotional: "Contentment comes from trusting in God's presence rather than possessions. His promise to never leave or forsake you is worth more than any amount of money. Find your satisfaction in Him.", prayer: "Lord, free me from the love of money. Teach me contentment, knowing that You will never leave me. Amen.", date: "" },
  { id: "172", verse: "My soul, wait thou only upon God; for my expectation is from him. He only is my rock and my salvation: he is my defence; I shall not be moved.", reference: "Psalm 127:1", devotional: "Without God's involvement, even the greatest human efforts are futile. Let Him be the architect and builder of your life, family, and endeavors. When He builds, it stands forever.", prayer: "Lord, build my house and my life. Without You, my labor is in vain. Be the foundation of everything I build. Amen.", date: "" },
  { id: "173", verse: "Blessed are they which do hunger and thirst after righteousness: for they shall be filled.", reference: "Psalm 37:7", devotional: "Patience before God means refusing to compare your journey with others. When people around you seem to prosper, trust that God has a unique plan for you. Wait on Him without fretting.", prayer: "Lord, help me to be still and patient. I will not fret but trust in Your unique plan for my life. Amen.", date: "" },
  { id: "174", verse: "But thou, O Lord, art a God full of compassion, and gracious, longsuffering, and plenteous in mercy and truth.", reference: "2 Corinthians 4:17", devotional: "Your present suffering is temporary, but the glory God is producing through it is eternal. Perspective changes everything. What seems heavy now is light compared to what is coming.", prayer: "Lord, help me to see my troubles as light and momentary. Fix my eyes on the eternal glory You are preparing. Amen.", date: "" },
  { id: "175", verse: "And he said unto me, My grace is sufficient for thee: for my strength is made perfect in weakness. Most gladly therefore will I rather glory in my infirmities, that the power of Christ may rest upon me.", reference: "Psalm 46:5", devotional: "When God dwells within you, you cannot be shaken. His presence brings stability and strength. At the dawn of each new day, He is there to help you stand firm.", prayer: "Lord, dwell within me so I will not fall. Help me at the break of each new day. Your presence is my stability. Amen.", date: "" },
  { id: "176", verse: "I will praise thee, O Lord, with my whole heart; I will shew forth all thy marvellous works. I will be glad and rejoice in thee: I will sing praise to thy name, O thou most High.", reference: "Proverbs 19:21", devotional: "You may have many ideas and strategies, but God's purposes are what ultimately come to pass. Align your plans with His will and watch His purpose unfold beautifully.", prayer: "Lord, let Your purposes prevail over my plans. Align my heart with Your will and Your way. Amen.", date: "" },
  { id: "177", verse: "A soft answer turneth away wrath: but grievous words stir up anger.", reference: "Psalm 23:2-3", devotional: "God knows you need rest and refreshment. He leads you to places of peace and renewal. Allow Him to restore your weary soul in His green pastures of grace.", prayer: "Lord, lead me to Your green pastures and quiet waters. Refresh my weary soul in Your presence. Amen.", date: "" },
  { id: "178", verse: "In the day when I cried thou answeredst me, and strengthenedst me with strength in my soul.", reference: "Romans 3:23", devotional: "Every person has sinned and needs God's grace. This truth levels the playing field and reminds us that we all need a Savior. No one is beyond the need for redemption.", prayer: "Lord, I acknowledge my sin and my need for Your grace. Thank You for Your mercy that covers all my shortcomings. Amen.", date: "" },
  { id: "179", verse: "Jesus said unto her, I am the resurrection, and the life: he that believeth in me, though he were dead, yet shall he live: and whosoever liveth and believeth in me shall never die.", reference: "Matthew 28:19", devotional: "The Great Commission is for every believer. You are called to share the gospel and make disciples wherever you go. This mission gives your life eternal purpose and significance.", prayer: "Lord, use me to make disciples. Give me boldness to share Your gospel with all nations and all people. Amen.", date: "" },
  { id: "180", verse: "I will bless the Lord at all times: his praise shall continually be in my mouth.", reference: "Isaiah 55:6", devotional: "There is an urgency to seeking God. Today is the day to draw close to Him and call upon His name. Don't delay your pursuit of His presence.", prayer: "Lord, I seek You while You may be found. I call on You while You are near. Draw me into Your presence. Amen.", date: "" },
  { id: "181", verse: "Rejoice evermore. Pray without ceasing. In every thing give thanks: for this is the will of God in Christ Jesus concerning you.", reference: "Psalm 97:1", devotional: "God is on His throne, and that is reason for the entire earth to celebrate. No matter what happens in the world, the Lord reigns supreme. Let this truth bring you gladness.", prayer: "Lord, You reign over all. Let my heart rejoice in Your sovereign rule. The earth is glad because You are King. Amen.", date: "" },
  { id: "182", verse: "For he shall give his angels charge over thee, to keep thee in all thy ways.", reference: "Matthew 5:4", devotional: "God does not waste your tears. He promises comfort to those who grieve. In your mourning, His gentle presence wraps around you, bringing healing and hope.", prayer: "Lord, comfort me in my mourning. Wrap me in Your gentle presence and turn my sorrow into joy. Amen.", date: "" },
  { id: "183", verse: "Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness.", reference: "Psalm 91:1-2", devotional: "Making God your dwelling place brings you under His protective shadow. He is your refuge and fortress, the safest place in existence. Trust Him and rest in His shelter.", prayer: "Lord, You are my refuge and fortress. I dwell in Your shelter and abide in Your shadow. I trust You completely. Amen.", date: "" },
  { id: "184", verse: "The Lord of hosts is with us; the God of Jacob is our refuge. Selah.", reference: "Proverbs 27:17", devotional: "God designed you for community. Meaningful relationships sharpen your character and deepen your faith. Surround yourself with people who challenge and encourage you to grow.", prayer: "Lord, bring people into my life who sharpen me. Help me to be an encouragement and challenge to others. Amen.", date: "" },
  { id: "185", verse: "Honour the Lord with thy substance, and with the firstfruits of all thine increase: so shall thy barns be filled with plenty, and thy presses shall burst out with new wine.", reference: "Psalm 9:9", devotional: "When injustice presses in and trouble surrounds you, God is your safe place. He is a stronghold for the oppressed and a defender of the weak. Run to Him for protection.", prayer: "Lord, be my refuge and stronghold. Protect me in times of trouble and defend me against oppression. Amen.", date: "" },
  { id: "186", verse: "From the end of the earth will I cry unto thee, when my heart is overwhelmed: lead me to the rock that is higher than I. For thou hast been a shelter for me, and a strong tower from the enemy.", reference: "Psalm 127:3", devotional: "Children are a precious gift from God, a heritage of His blessing. Whether your own children or those He places in your life, treasure them as rewards from His loving hand.", prayer: "Lord, thank You for the gift of children. Help me to treasure and nurture them as Your precious heritage. Amen.", date: "" },
  { id: "187", verse: "Therefore I say unto you, Take no thought for your life, what ye shall eat, or what ye shall drink; nor yet for your body, what ye shall put on. Is not the life more than meat, and the body than raiment? Behold the fowls of the air: for they sow not, neither do they reap, nor gather into barns; yet your heavenly Father feedeth them. Are ye not much better than they?", reference: "Matthew 7:12", devotional: "The Golden Rule summarizes God's expectations for how we treat others. It is simple yet transformative. Treat every person with the same respect and kindness you desire for yourself.", prayer: "Lord, help me to treat others as I want to be treated. Let the Golden Rule govern all my interactions. Amen.", date: "" },
  { id: "188", verse: "I have set the Lord always before me: because he is at my right hand, I shall not be moved.", reference: "Isaiah 26:3", devotional: "Perfect peace comes from a mind focused on God. When your thoughts are anchored in His faithfulness, anxiety loses its grip. Trust Him and experience His supernatural peace.", prayer: "Lord, keep me in perfect peace as I fix my mind on You. I trust in Your faithfulness. Amen.", date: "" },
  { id: "189", verse: "There is therefore now no condemnation to them which are in Christ Jesus, who walk not after the flesh, but after the Spirit.", reference: "Luke 6:36", devotional: "Mercy is a defining trait of God, and He calls you to reflect it. When you show mercy to others, you become more like your heavenly Father. Extend the grace you have received.", prayer: "Lord, make me merciful as You are merciful. Help me to extend grace and compassion to everyone I encounter. Amen.", date: "" },
  { id: "190", verse: "What time I am afraid, I will trust in thee. In God I will praise his word, in God I have put my trust; I will not fear what flesh can do unto me.", reference: "Psalm 98:1", devotional: "God's marvelous deeds deserve a fresh song of praise. Don't let your worship become routine. Let the wonder of what He has done inspire new expressions of gratitude and praise.", prayer: "Lord, I sing a new song to You. You have done marvelous things. Let my praise be fresh and joyful. Amen.", date: "" },
  { id: "191", verse: "But without faith it is impossible to please him: for he that cometh to God must believe that he is, and that he is a rewarder of them that diligently seek him.", reference: "1 Corinthians 2:2", devotional: "The cross of Christ is the center of the Christian message. Everything else finds its meaning in the crucified and risen Savior. Keep Christ and His sacrifice at the heart of your faith.", prayer: "Lord, let Christ and Him crucified be the center of my life and message. Nothing else matters as much. Amen.", date: "" },
  { id: "192", verse: "But the salvation of the righteous is of the Lord: he is their strength in the time of trouble. And the Lord shall help them, and deliver them: he shall deliver them from the wicked, and save them, because they trust in him.", reference: "Psalm 150:6", devotional: "Every living creature is invited to praise God. If you have breath, you have reason to praise. Let your life be an ongoing expression of worship to the Creator.", prayer: "Lord, let everything within me praise You. As long as I have breath, I will worship and honor Your name. Amen.", date: "" },
  { id: "193", verse: "If the Son therefore shall make you free, ye shall be free indeed.", reference: "John 11:25", devotional: "Jesus holds power over death itself. Believing in Him guarantees eternal life beyond the grave. This promise removes the sting of death and fills you with confident hope.", prayer: "Jesus, You are the resurrection and the life. I believe in You and trust in Your promise of eternal life. Amen.", date: "" },
  { id: "194", verse: "Shew me thy ways, O Lord; teach me thy paths. Lead me in thy truth, and teach me: for thou art the God of my salvation; on thee do I wait all the day.", reference: "Hebrews 13:8", devotional: "In a world of constant change, Jesus remains the same. His character, His promises, and His love are unchanging. You can always depend on Him because He never changes.", prayer: "Lord Jesus, thank You for being the same yesterday, today, and forever. I rest in Your unchanging faithfulness. Amen.", date: "" },
  { id: "195", verse: "Every word of God is pure: he is a shield unto them that put their trust in him.", reference: "Hebrews 10:24", devotional: "We are called to actively encourage one another toward love and service. Community is not just about receiving but about spurring others on to greater faithfulness and good works.", prayer: "Lord, show me how to encourage others toward love and good deeds. Let me be a catalyst for godliness. Amen.", date: "" },
  { id: "196", verse: "And he hath put a new song in my mouth, even praise unto our God: many shall see it, and fear, and shall trust in the Lord.", reference: "Psalm 16:8", devotional: "When you keep God always before you, everything else falls into proper perspective. His presence at your side ensures your stability. You cannot be shaken when He is your focus.", prayer: "Lord, I set You always before me. Because You are at my right hand, I will not be shaken. Amen.", date: "" },
  { id: "197", verse: "But ye are a chosen generation, a royal priesthood, an holy nation, a peculiar people; that ye should shew forth the praises of him who hath called you out of darkness into his marvellous light.", reference: "Psalm 149:4", devotional: "God delights in you. He takes pleasure in His people and grants victory to the humble. Walk in humility and receive the crown of victory He has prepared for you.", prayer: "Lord, thank You for delighting in me. Crown me with victory as I walk humbly before You. Amen.", date: "" },
  { id: "198", verse: "Great is the Lord, and greatly to be praised; and his greatness is unsearchable.", reference: "Proverbs 14:29", devotional: "Patience reveals wisdom while a quick temper reveals foolishness. When you practice patience, you demonstrate a deep understanding of God's ways. Ask Him for patience today.", prayer: "Lord, grant me patience and understanding. Keep me from a quick temper and help me respond with wisdom. Amen.", date: "" },
  { id: "199", verse: "Blessed are the pure in heart: for they shall see God.", reference: "2 Corinthians 4:6", devotional: "The same God who created light now shines in your heart. He reveals His glory through the face of Jesus Christ. This inner illumination transforms how you see everything.", prayer: "Lord, shine Your light in my heart. Let me see Your glory displayed in the face of Christ. Amen.", date: "" },
  { id: "200", verse: "Restore unto me the joy of thy salvation; and uphold me with thy free spirit.", reference: "John 7:38", devotional: "The Holy Spirit within you is like a river of living water, bringing life and refreshment wherever you go. As you believe in Jesus, His Spirit flows from you to bless others.", prayer: "Jesus, let rivers of living water flow from within me. Fill me with Your Spirit to refresh everyone I encounter. Amen.", date: "" },
  { id: "201", verse: "And therefore will the Lord wait, that he may be gracious unto you, and therefore will he be exalted, that he may have mercy upon you: for the Lord is a God of judgment: blessed are all they that wait for him.", reference: "Nahum 1:3", devotional: "God's patience is matched by His immense power. He is not slow because He is weak, but because He is merciful. His power and patience work together for your benefit.", prayer: "Lord, thank You for being slow to anger and great in power. Let Your patience inspire me to extend grace to others. Amen.", date: "" },
  { id: "202", verse: "For this God is our God for ever and ever: he will be our guide even unto death.", reference: "Proverbs 12:25", devotional: "Anxiety is heavy, but encouragement is light. A kind word at the right time can lift a burdened soul. Be the voice of encouragement that someone needs today.", prayer: "Lord, replace my anxiety with Your peace. Use me to speak kind words that cheer the hearts of others. Amen.", date: "" },
  { id: "203", verse: "Let the word of Christ dwell in you richly in all wisdom; teaching and admonishing one another in psalms and hymns and spiritual songs, singing with grace in your hearts to the Lord.", reference: "Ecclesiastes 3:1", devotional: "God has ordained seasons for every part of life. Trust His timing and embrace the season you are in. He is purposeful in every transition and every moment.", prayer: "Lord, help me to embrace the season I am in. Thank You for Your perfect timing in all things. Amen.", date: "" },
  { id: "204", verse: "Come and hear, all ye that fear God, and I will declare what he hath done for my soul. I cried unto him with my mouth, and he was extolled with my tongue.", reference: "Psalm 145:17", devotional: "God's justice and faithfulness are unwavering. In all His ways, He is righteous and true. You can trust His judgments and rely on His faithfulness in every situation.", prayer: "Lord, You are just in all Your ways and faithful in all You do. I trust Your righteous character completely. Amen.", date: "" },
  { id: "205", verse: "And God is able to make all grace abound toward you; that ye, always having all sufficiency in all things, may abound to every good work.", reference: "Genesis 9:13", devotional: "The rainbow is a visible reminder of God's covenant faithfulness. He keeps His promises, and every rainbow is a testimony to His reliability. Trust in His covenants with you.", prayer: "Lord, thank You for Your covenant promises. Like the rainbow, Your faithfulness is a constant reminder of Your love. Amen.", date: "" },
  { id: "206", verse: "The fear of the Lord is the beginning of wisdom: a good understanding have all they that do his commandments: his praise endureth for ever.", reference: "Lamentations 3:22", devotional: "God's love is the reason you are not overwhelmed. His compassion toward you never runs out. Even in the darkest times, His love sustains and preserves you.", prayer: "Lord, thank You that Your great love keeps me from being consumed. Your compassions never fail me. Amen.", date: "" },
  { id: "207", verse: "A merry heart doeth good like a medicine: but a broken spirit drieth the bones.", reference: "2 Corinthians 4:16", devotional: "Even when the outward circumstances deteriorate, your inner being is being refreshed and renewed by God's Spirit. Don't lose heart — transformation is happening from the inside out.", prayer: "Lord, renew me inwardly even as outward things fade. I will not lose heart because You are at work within me. Amen.", date: "" },
  { id: "208", verse: "The meek will he guide in judgment: and the meek will he teach his way.", reference: "Proverbs 18:22", devotional: "A godly marriage is a blessing from God. He designed relationships to bring joy, companionship, and mutual growth. Treasure the relationships God has placed in your life.", prayer: "Lord, thank You for the gift of meaningful relationships. Help me to honor and cherish those You have placed in my life. Amen.", date: "" },
  { id: "209", verse: "And Jesus said unto them, I am the bread of life: he that cometh to me shall never hunger; and he that believeth on me shall never thirst.", reference: "Revelation 3:20", devotional: "Jesus doesn't force His way into your life. He gently knocks and waits for your invitation. When you open the door, He enters and brings intimate fellowship with Him.", prayer: "Jesus, I hear Your knock and I open the door of my heart. Come in and fellowship with me. I welcome Your presence. Amen.", date: "" },
  { id: "210", verse: "For thou art my hope, O Lord God: thou art my trust from my youth. By thee have I been holden up from the womb: thou art he that took me out of my mother's bowels: my praise shall be continually of thee.", reference: "2 Timothy 2:1", devotional: "Strength in the Christian life comes from grace, not self-effort. Be strong in the grace that flows from Christ Jesus. His grace empowers you for every challenge and calling.", prayer: "Lord, I am strong in Your grace. Let the grace of Christ Jesus empower me for every task and trial. Amen.", date: "" },
  { id: "211", verse: "Be kindly affectioned one to another with brotherly love; in honour preferring one another.", reference: "Micah 7:7", devotional: "In a world of uncertainty, fix your gaze on the Lord. Wait for Him with confident expectation. He hears your prayers and His salvation is sure.", prayer: "Lord, I look to You and wait for Your salvation. I know You hear me. My hope is in You alone. Amen.", date: "" },
  { id: "212", verse: "It is a good thing to give thanks unto the Lord, and to sing praises unto thy name, O most High: to shew forth thy lovingkindness in the morning, and thy faithfulness every night.", reference: "Mark 16:15", devotional: "The call to share the good news is universal. Every believer is commissioned to carry the gospel wherever they go. Your sphere of influence is your mission field.", prayer: "Lord, give me boldness to share the gospel. Use me to reach others with the good news of Jesus Christ. Amen.", date: "" },
  { id: "213", verse: "Jesus Christ the same yesterday, and to day, and for ever.", reference: "Psalm 145:14", devotional: "When you stumble and fall, God is there to catch you. When the weight of life bows you down, He lifts you up. His hands are always ready to support and restore.", prayer: "Lord, uphold me when I fall and lift me when I am bowed down. Your supporting hands never fail. Amen.", date: "" },
  { id: "214", verse: "Thy word have I hid in mine heart, that I might not sin against thee.", reference: "James 3:17", devotional: "Heavenly wisdom looks very different from worldly wisdom. It is pure, peaceful, gentle, and full of mercy. Seek this kind of wisdom from God and let it transform your relationships.", prayer: "Lord, give me heavenly wisdom that is pure, peace-loving, and full of mercy. Transform my thinking with Your truth. Amen.", date: "" },
  { id: "215", verse: "And the Lord shall guide thee continually, and satisfy thy soul in drought, and make fat thy bones: and thou shalt be like a watered garden, and like a spring of water, whose waters fail not.", reference: "Mark 11:22", devotional: "These simple words from Jesus carry profound power. Faith in God is the foundation of everything in the Christian life. Let your faith be firmly rooted in who He is.", prayer: "Lord, I have faith in You. Strengthen my belief and deepen my trust. You are faithful and worthy of all my confidence. Amen.", date: "" },
  { id: "216", verse: "Thou preparest a table before me in the presence of mine enemies: thou anointest my head with oil; my cup runneth over.", reference: "2 Corinthians 3:18", devotional: "As you gaze upon God's glory, you are being progressively transformed into His likeness. This transformation is ongoing and increasing. Keep your eyes on Him and become more like Him.", prayer: "Lord, transform me into Your image with ever-increasing glory. As I behold You, make me more like You. Amen.", date: "" },
  { id: "217", verse: "In the fear of the Lord is strong confidence: and his children shall have a place of refuge.", reference: "Job 36:15", devotional: "God uses suffering as a doorway to deeper revelation. In your affliction, He speaks tenderly and delivers you. Pain is not pointless when it brings you closer to hearing His voice.", prayer: "Lord, speak to me in my suffering. Use my affliction to draw me closer to You and to deepen my faith. Amen.", date: "" },
  { id: "218", verse: "Be of good courage, and he shall strengthen your heart, all ye that hope in the Lord.", reference: "John 10:11", devotional: "Jesus is the Good Shepherd who sacrificed His life for you. His love for His sheep is unconditional and sacrificial. You are safe, protected, and deeply loved by your Shepherd.", prayer: "Jesus, You are the Good Shepherd. Thank You for laying down Your life for me. I follow You with grateful trust. Amen.", date: "" },
  { id: "219", verse: "And Jesus came and spake unto them, saying, All power is given unto me in heaven and in earth. Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Holy Ghost.", reference: "Hebrews 11:6", devotional: "Faith is essential to your relationship with God. Believing that He exists and rewards seekers is the foundation of pleasing Him. Earnest seeking is always met with divine reward.", prayer: "Lord, I believe that You exist and that You reward those who seek You. Increase my faith and my earnest pursuit of You. Amen.", date: "" },
  { id: "220", verse: "I love the Lord, because he hath heard my voice and my supplications. Because he hath inclined his ear unto me, therefore will I call upon him as long as I live.", reference: "Hebrews 4:16", devotional: "God's throne is a throne of grace, not judgment. You can approach Him with boldness and confidence. In your time of need, mercy and grace are waiting for you there.", prayer: "Lord, I approach Your throne of grace with confidence. Grant me mercy and grace in my time of need. Amen.", date: "" },
  { id: "221", verse: "But as it is written, Eye hath not seen, nor ear heard, neither have entered into the heart of man, the things which God hath prepared for them that love him.", reference: "John 10:10", devotional: "Jesus came to give you abundant life, not just existence. The enemy seeks to steal your joy, but Christ offers fullness of life. Choose the abundant life Jesus provides.", prayer: "Jesus, thank You for coming to give me life to the full. Guard me from the thief and fill me with abundance. Amen.", date: "" },
  { id: "222", verse: "The Lord is good to all: and his tender mercies are over all his works.", reference: "Matthew 6:25", devotional: "Jesus addresses our most common worries: provision and appearance. He assures you that your heavenly Father knows your needs. Release your anxiety and trust His care.", prayer: "Lord, I release my worries about provision and daily needs. You know what I need and You will provide. Amen.", date: "" },
  { id: "223", verse: "A new commandment I give unto you, That ye love one another; as I have loved you, that ye also love one another.", reference: "Matthew 6:26", devotional: "If God feeds the birds, how much more will He provide for you, His beloved child? Your value to Him is immeasurable. Trust His provision and stop worrying.", prayer: "Lord, I am more valuable to You than the birds. Thank You for Your faithful provision. I trust You to care for me. Amen.", date: "" },
  { id: "224", verse: "I wait for the Lord, my soul doth wait, and in his word do I hope.", reference: "Matthew 28:20", devotional: "Jesus promises His constant presence as you fulfill His mission. He is with you always, not just sometimes. His presence empowers you to obey His commands and fulfill His calling.", prayer: "Jesus, thank You for being with me always. Help me to obey Your commands and fulfill Your mission. Amen.", date: "" },
  { id: "225", verse: "Heaviness in the heart of man maketh it stoop: but a good word maketh it glad.", reference: "Isaiah 53:4", devotional: "Jesus bore your pain and carried your sorrows on the cross. He understands your suffering because He experienced it Himself. You are not alone in your grief; He carries it with you.", prayer: "Lord Jesus, thank You for bearing my griefs and carrying my sorrows. I bring all my pain to You. Amen.", date: "" },
  { id: "226", verse: "Great is our Lord, and of great power: his understanding is infinite.", reference: "Proverbs 18:21", devotional: "Your words carry tremendous power. They can build up or tear down, give life or bring death. Choose to speak words that bring life, encouragement, and hope to those around you.", prayer: "Lord, tame my tongue. Help me to speak words of life and not death. Let my speech bring blessing and encouragement. Amen.", date: "" },
  { id: "227", verse: "And not only so, but we glory in tribulations also: knowing that tribulation worketh patience; and patience, experience; and experience, hope.", reference: "Hebrews 4:12", devotional: "God's Word is not a dead text but a living force. It discerns the deepest parts of your being and brings transformation. Engage with Scripture daily and let it reshape your life.", prayer: "Lord, let Your living Word penetrate my heart and transform my life. Make me sensitive to its power. Amen.", date: "" },
  { id: "228", verse: "I will both lay me down in peace, and sleep: for thou, Lord, only makest me dwell in safety.", reference: "Numbers 6:24-26", devotional: "This priestly blessing captures God's complete desire for you: blessing, protection, radiance, grace, attention, and peace. Receive every aspect of this beautiful benediction today.", prayer: "Lord, bless me and keep me. Make Your face shine upon me and give me peace. I receive Your full blessing. Amen.", date: "" },
  { id: "229", verse: "Hast thou not known? hast thou not heard, that the everlasting God, the Lord, the Creator of the ends of the earth, fainteth not, neither is weary? there is no searching of his understanding.", reference: "Matthew 5:5", devotional: "Meekness is not weakness but strength under control. Those who are gentle and humble will ultimately receive God's greatest inheritance. True power comes through submitted strength.", prayer: "Lord, make me meek and gentle. Help me to demonstrate strength under Your control. I trust in Your promises. Amen.", date: "" },
  { id: "230", verse: "Make a joyful noise unto God, all ye lands: sing forth the honour of his name: make his praise glorious.", reference: "Psalm 16:11", devotional: "God reveals the path to true life, which leads to fullness of joy in His presence. The greatest pleasures are found at His right hand, not in the fleeting offerings of this world.", prayer: "Lord, make known to me the path of life. Fill me with joy in Your presence and eternal pleasures at Your right hand. Amen.", date: "" },
  { id: "231", verse: "And whatsoever ye do in word or deed, do all in the name of the Lord Jesus, giving thanks to God and the Father by him.", reference: "James 4:6", devotional: "Pride positions you against God, while humility opens the door to His favor. Choose humility in every interaction and relationship. God's grace flows freely to the humble heart.", prayer: "Lord, keep me humble before You. Remove all pride from my heart and shower me with Your favor and grace. Amen.", date: "" },
  { id: "232", verse: "But I have trusted in thy mercy; my heart shall rejoice in thy salvation. I will sing unto the Lord, because he hath dealt bountifully with me.", reference: "Romans 11:33", devotional: "God's wisdom is infinitely deep and His knowledge is beyond measure. When His ways seem mysterious, trust that His understanding is perfect. His paths are higher than yours.", prayer: "Lord, I stand in awe of Your infinite wisdom and knowledge. When I don't understand, I trust Your perfect judgment. Amen.", date: "" },
  { id: "233", verse: "Blessed are the peacemakers: for they shall be called the children of God.", reference: "1 Corinthians 15:57", devotional: "Victory is not something you achieve on your own; it is a gift from God through Jesus Christ. Every battle you face has already been won. Walk in the victory He has provided.", prayer: "Lord, thank You for giving me victory through Jesus Christ. Help me to walk in the triumph He has secured. Amen.", date: "" },
  { id: "234", verse: "Bless the Lord, O my soul, and forget not all his benefits: who forgiveth all thine iniquities; who healeth all thy diseases; who redeemeth thy life from destruction; who crowneth thee with lovingkindness and tender mercies.", reference: "Psalm 139:7", devotional: "God's presence is inescapable, and that is a beautiful truth. No matter where you go or what you face, He is there. You can never outrun His love or His care.", prayer: "Lord, thank You that I can never escape Your presence. Wherever I go, You are there. I am never alone. Amen.", date: "" },
  { id: "235", verse: "The Lord is not slack concerning his promise, as some men count slackness; but is longsuffering to us-ward, not willing that any should perish, but that all should come to repentance.", reference: "Habakkuk 3:19", devotional: "God gives you the agility and confidence to navigate life's mountains. Like a deer on high terrain, He makes your steps sure. His strength enables you to reach spiritual heights.", prayer: "Lord, be my strength. Make my feet sure as I walk upon the high places You have called me to. Amen.", date: "" },
  { id: "236", verse: "Praise ye the Lord. Sing unto the Lord a new song, and his praise in the congregation of saints.", reference: "John 3:17", devotional: "God's mission through Jesus was salvation, not condemnation. He came to rescue, not to punish. If God does not condemn you in Christ, you need not condemn yourself.", prayer: "Lord, thank You for sending Jesus to save me, not condemn me. I receive Your salvation with a grateful heart. Amen.", date: "" },
  { id: "237", verse: "Strength and honour are her clothing; and she shall rejoice in time to come.", reference: "Psalm 126:5", devotional: "Your tears are seeds of future joy. The painful seasons of sowing will give way to a joyful harvest. Don't despise the season of tears; joy is coming.", prayer: "Lord, turn my tears into seeds of joy. I trust that what I sow in sorrow will reap songs of gladness. Amen.", date: "" },
  { id: "238", verse: "O come, let us sing unto the Lord: let us make a joyful noise to the rock of our salvation. Let us come before his presence with thanksgiving, and make a joyful noise unto him with psalms.", reference: "2 Corinthians 12:10", devotional: "Boasting in weakness seems paradoxical, but it is the path to experiencing Christ's power. When you acknowledge your limitations, you make room for His unlimited strength.", prayer: "Lord, I boast in my weaknesses so that Your power may rest upon me. My weakness is Your opportunity. Amen.", date: "" },
  { id: "239", verse: "In my Father's house are many mansions: if it were not so, I would have told you. I go to prepare a place for you. And if I go and prepare a place for you, I will come again, and receive you unto myself; that where I am, there ye may be also.", reference: "Jeremiah 1:5", devotional: "Before you took your first breath, God already knew you intimately and set you apart for a purpose. Your life is not random but divinely planned from before birth.", prayer: "Lord, You knew me before I was born and set me apart for Your purposes. Help me to walk in Your calling. Amen.", date: "" },
  { id: "240", verse: "O clap your hands, all ye people; shout unto God with the voice of triumph.", reference: "Isaiah 25:1", devotional: "God's faithfulness is perfect, and His deeds are wonderful. He deserves to be exalted and praised for all He has done. Let your life be a testimony to His wonderful works.", prayer: "Lord, You are my God. I exalt You and praise Your name for Your perfect faithfulness and wonderful deeds. Amen.", date: "" },
  { id: "241", verse: "Likewise the Spirit also helpeth our infirmities: for we know not what we should pray for as we ought: but the Spirit itself maketh intercession for us with groanings which cannot be uttered.", reference: "Psalm 90:12", devotional: "Life is precious and fleeting. When you recognize the brevity of your days, you gain wisdom about what truly matters. Live each day with purpose and eternal perspective.", prayer: "Lord, teach me to number my days. Give me a heart of wisdom to live each day with purpose and gratitude. Amen.", date: "" },
  { id: "242", verse: "Thou art my hiding place and my shield: I hope in thy word.", reference: "1 Corinthians 15:58", devotional: "Stand firm in your faith and give yourself fully to God's work. Nothing you do for the Lord is wasted. Your labor has eternal significance and will produce lasting fruit.", prayer: "Lord, help me to stand firm and give myself fully to Your work. I know my labor in You is not in vain. Amen.", date: "" },
  { id: "243", verse: "Let us hold fast the profession of our faith without wavering; for he is faithful that promised.", reference: "Psalm 31:24", devotional: "Strength and courage are available to all who wait on God. The waiting season is not a season of weakness but of building spiritual muscle. Take courage as you wait for Him.", prayer: "Lord, strengthen me and give my heart courage as I wait for You. I trust that Your timing is perfect. Amen.", date: "" },
  { id: "244", verse: "O Lord our Lord, how excellent is thy name in all the earth! who hast set thy glory above the heavens.", reference: "John 1:12", devotional: "Through faith in Jesus, you receive the incredible privilege of becoming God's child. This is your highest identity and your greatest security. You belong to the family of God.", prayer: "Lord, thank You for the right to be called Your child. I receive this privilege with joy and gratitude. Amen.", date: "" },
  { id: "245", verse: "Can a woman forget her sucking child, that she should not have compassion on the son of her womb? yea, they may forget, yet will I not forget thee. Behold, I have graven thee upon the palms of my hands; thy walls are continually before me.", reference: "Ephesians 1:7", devotional: "Through the blood of Jesus, you are redeemed and forgiven. This is not based on your merit but on the riches of God's grace. Your sins are completely washed away in Christ.", prayer: "Lord, thank You for redemption and forgiveness through the blood of Jesus. Your grace is rich and abundant. Amen.", date: "" },
  { id: "246", verse: "Ye that love the Lord, hate evil: he preserveth the souls of his saints; he delivereth them out of the hand of the wicked.", reference: "Psalm 37:23", devotional: "When you walk in righteousness, God personally orders your steps. He delights in your journey and directs each step with care. Trust His guidance for every area of your life.", prayer: "Lord, order my steps today. I trust You to direct my path. Thank You for delighting in my journey with You. Amen.", date: "" },
  { id: "247", verse: "A man that hath friends must shew himself friendly: and there is a friend that sticketh closer than a brother.", reference: "Song of Solomon 2:4", devotional: "God invites you into His banqueting house of abundance and covers you with the banner of His love. His love is not hidden but displayed openly for all to see. You are loved extravagantly.", prayer: "Lord, thank You for Your banner of love over me. I rest in Your abundant provision and unfailing affection. Amen.", date: "" },
  { id: "248", verse: "O sing unto the Lord a new song; for he hath done marvellous things: his right hand, and his holy arm, hath gotten him the victory.", reference: "Lamentations 3:24", devotional: "When God is your portion, you have everything you need. He is your inheritance, your satisfaction, and your hope. Find your completeness in Him alone.", prayer: "Lord, You are my portion and my hope. In You I find everything I need. My soul is satisfied in You. Amen.", date: "" },
  { id: "249", verse: "After this manner therefore pray ye: Our Father which art in heaven, Hallowed be thy name. Thy kingdom come. Thy will be done in earth, as it is in heaven.", reference: "Philippians 4:5", devotional: "Gentleness is a visible sign of Christ's character in you. Let it be evident in every interaction. Remember that the Lord is near, watching and empowering your gentle spirit.", prayer: "Lord, let my gentleness be evident to all. You are near, and Your presence makes me gentle and kind. Amen.", date: "" },
  { id: "250", verse: "Blessed is he whose transgression is forgiven, whose sin is covered.", reference: "Psalm 138:1", devotional: "Wholehearted praise is the response of a grateful soul. Declare God's praises boldly and unashamedly. Let your worship be a testimony of His greatness to all who hear.", prayer: "Lord, I praise You with all my heart. Let my worship declare Your greatness to everyone around me. Amen.", date: "" },
  { id: "251", verse: "There is no fear in love; but perfect love casteth out fear: because fear hath torment. He that feareth is not made perfect in love.", reference: "Romans 8:35", devotional: "Paul's rhetorical question has only one answer: nothing can separate you from Christ's love. No hardship, no danger, no circumstance can break the bond of His love for you.", prayer: "Lord, thank You that nothing can separate me from Your love. No trouble or hardship can break our bond. Amen.", date: "" },
  { id: "252", verse: "Behold, the eye of the Lord is upon them that fear him, upon them that hope in his mercy.", reference: "Psalm 139:13", devotional: "God personally and intimately crafted you. He knit you together with care and purpose. Every part of your being was designed by His loving hands. You are His handiwork.", prayer: "Lord, thank You for knitting me together. I am Your handiwork, made with love and purpose. I celebrate how You made me. Amen.", date: "" },
  { id: "253", verse: "But as many as received him, to them gave he power to become the sons of God, even to them that believe on his name.", reference: "Romans 12:14", devotional: "Responding to persecution with blessing is a radical act of faith. It goes against human nature but aligns with God's nature. Choose to bless even those who mistreat you.", prayer: "Lord, give me the grace to bless those who persecute me. Help me to respond with love, not cursing. Amen.", date: "" },
  { id: "254", verse: "The Lord liveth; and blessed be my rock; and let the God of my salvation be exalted.", reference: "Luke 6:38", devotional: "Generosity triggers God's overflowing provision. When you give freely, God returns to you in abundance. His measure is always greater than yours. Be generous and watch Him multiply.", prayer: "Lord, make me generous. As I give, pour out Your blessings in good measure, pressed down and running over. Amen.", date: "" },
  { id: "255", verse: "For whatsoever things were written aforetime were written for our learning, that we through patience and comfort of the scriptures might have hope.", reference: "Ephesians 1:22", devotional: "Christ reigns supreme over all things, and He has been given as head of the church. His authority covers everything you face. Trust in His headship over your life and your community of faith.", prayer: "Lord Jesus, You are head over all things. I submit to Your authority and trust in Your supreme reign. Amen.", date: "" },
  { id: "256", verse: "He shall not be afraid of evil tidings: his heart is fixed, trusting in the Lord.", reference: "Matthew 7:11", devotional: "God's generosity far exceeds even the best human parents. He delights in giving good gifts to His children. Ask Him with confidence and receive His generous provision.", prayer: "Father, thank You for being a generous God. I ask for Your good gifts today, knowing You delight in providing. Amen.", date: "" },
  { id: "257", verse: "Pleasant words are as an honeycomb, sweet to the soul, and health to the bones.", reference: "1 Peter 5:10", devotional: "Suffering is temporary, but God's restoration is eternal. After the trial, He personally restores, confirms, strengthens, and establishes you. Your suffering has a glorious ending.", prayer: "Lord, restore, confirm, strengthen, and establish me after this season of suffering. I trust in Your eternal glory. Amen.", date: "" },
  { id: "258", verse: "The law of the Lord is perfect, converting the soul: the testimony of the Lord is sure, making wise the simple.", reference: "Romans 1:16", devotional: "The gospel is God's power for salvation. Never be ashamed of its message. It has the power to transform lives, break chains, and bring eternal hope to everyone who believes.", prayer: "Lord, I am not ashamed of Your gospel. Give me boldness to share its life-changing power with everyone. Amen.", date: "" },
  { id: "259", verse: "I have fought a good fight, I have finished my course, I have kept the faith.", reference: "Revelation 21:4", devotional: "A day is coming when all suffering will end. God will personally wipe away every tear. This promise of a pain-free eternity gives you hope to endure present difficulties.", prayer: "Lord, I look forward to the day when there are no more tears. Thank You for the hope of Your eternal kingdom. Amen.", date: "" },
  { id: "260", verse: "But I trusted in thee, O Lord: I said, Thou art my God. My times are in thy hand: deliver me from the hand of mine enemies, and from them that persecute me.", reference: "Proverbs 2:6", devotional: "Wisdom is a gift from God, not something achieved through human effort alone. When you seek Him, He generously pours out knowledge and understanding. Ask and you shall receive.", prayer: "Lord, give me Your wisdom today. Let knowledge and understanding flow from Your Word into my life. Amen.", date: "" },
  { id: "261", verse: "And even to your old age I am he; and even to hoar hairs will I carry you: I have made, and I will bear; even I will carry, and will deliver you.", reference: "Philippians 3:14", devotional: "The Christian life is a forward-moving journey. Don't look back at past failures or rest on past successes. Press on toward the heavenly prize God has prepared for you.", prayer: "Lord, help me to press on toward the goal. I fix my eyes on the heavenly prize You have prepared for me. Amen.", date: "" },
  { id: "262", verse: "Blessed be the Lord, who daily loadeth us with benefits, even the God of our salvation. Selah.", reference: "Romans 12:9", devotional: "Genuine love requires discernment. It means rejecting evil and clinging to good. This is not a passive love but an active choice to pursue what is right and true.", prayer: "Lord, make my love genuine. Help me to hate evil and hold fast to what is good in Your sight. Amen.", date: "" },
  { id: "263", verse: "For by him were all things created, that are in heaven, and that are in earth, visible and invisible, whether they be thrones, or dominions, or principalities, or powers: all things were created by him, and for him: and he is before all things, and by him all things consist.", reference: "1 Timothy 6:7", devotional: "This truth puts everything in perspective. Material possessions are temporary, but your relationship with God is eternal. Invest in what lasts and hold loosely to what doesn't.", prayer: "Lord, help me to hold loosely to material things. Let me invest in the eternal treasures of Your kingdom. Amen.", date: "" },
  { id: "264", verse: "Mercy and truth are met together; righteousness and peace have kissed each other.", reference: "James 4:7", devotional: "Submission to God is your greatest weapon against the enemy. When you yield to God's authority and resist the devil, he must flee. Your surrender to God is your victory.", prayer: "Lord, I submit to You. I resist the devil in Jesus' name. Thank You that he must flee from me. Amen.", date: "" },
  { id: "265", verse: "Therefore whosoever heareth these sayings of mine, and doeth them, I will liken him unto a wise man, which built his house upon a rock: and the rain descended, and the floods came, and the winds blew, and beat upon that house; and it fell not: for it was founded upon a rock.", reference: "Joshua 1:7", devotional: "Success in God's eyes comes from faithful obedience to His Word. Don't deviate from His instructions. Stay on the path He has laid out and you will prosper in all you do.", prayer: "Lord, help me to obey Your Word faithfully. Keep me on Your path so I may succeed in all You call me to. Amen.", date: "" },
  { id: "266", verse: "For thou wilt light my candle: the Lord my God will enlighten my darkness.", reference: "1 John 4:19", devotional: "Your capacity to love originates from God's love for you. He loved you first, and that love awakened your ability to love others. Every act of love you show traces back to His initiative.", prayer: "Lord, thank You for loving me first. Let my love for others flow from the love You have shown me. Amen.", date: "" },
  { id: "267", verse: "But the God of all grace, who hath called us unto his eternal glory by Christ Jesus, after that ye have suffered a while, make you perfect, stablish, strengthen, settle you.", reference: "Isaiah 26:4", devotional: "God is the eternal Rock that can never be moved. Your trust in Him is never misplaced. He stands firm through every storm, every age, and every circumstance.", prayer: "Lord, You are my eternal Rock. I trust in You forever. Nothing can shake the foundation You provide. Amen.", date: "" },
  { id: "268", verse: "For thou art my rock and my fortress; therefore for thy name's sake lead me, and guide me.", reference: "Psalm 23:3", devotional: "God is the restorer of weary souls. He leads you not just to any path but to paths of righteousness. He does this for His glory, which means it is guaranteed to happen.", prayer: "Lord, restore my soul and lead me in paths of righteousness. I follow You for the sake of Your name. Amen.", date: "" },
  { id: "269", verse: "He that handleth a matter wisely shall find good: and whoso trusteth in the Lord, happy is he.", reference: "1 Corinthians 10:13", devotional: "You are not alone in your struggles against temptation. God faithfully limits the intensity of every test and provides a way of escape. Trust His faithfulness in your moments of weakness.", prayer: "Lord, thank You for being faithful in my temptations. Show me the way of escape and strengthen me to overcome. Amen.", date: "" },
  { id: "270", verse: "For in the time of trouble he shall hide me in his pavilion: in the secret of his tabernacle shall he hide me; he shall set me up upon a rock.", reference: "Isaiah 46:9", devotional: "There is no one like God. He stands alone in power, wisdom, and love. Remember what He has done in the past and trust Him for the future. He is unique and unmatched.", prayer: "Lord, there is no other God like You. I remember Your faithfulness and trust You for what lies ahead. Amen.", date: "" },
  { id: "271", verse: "As the Father hath loved me, so have I loved you: continue ye in my love.", reference: "John 15:12", devotional: "Jesus sets the standard for love: as He has loved you. This is sacrificial, unconditional, and enduring love. Let His love be the model for how you love others.", prayer: "Jesus, help me to love others as You have loved me. Let my love be sacrificial, generous, and true. Amen.", date: "" },
  { id: "272", verse: "I have called upon thee, for thou wilt hear me, O God: incline thine ear unto me, and hear my speech.", reference: "Psalm 121:8", devotional: "God's watchful care extends to every departure and every arrival. He guards your going out and your coming in, now and forever. You are under constant divine surveillance of love.", prayer: "Lord, watch over my coming and going. Guard me now and forevermore. Your watchful care is my security. Amen.", date: "" },
  { id: "273", verse: "Nay, in all these things we are more than conquerors through him that loved us.", reference: "James 3:16", devotional: "Jealousy and selfish ambition bring chaos and destruction. Guard your heart against these toxic attitudes. Seek God's kingdom purposes above personal gain and experience His peace.", prayer: "Lord, cleanse my heart of jealousy and selfish ambition. Replace them with contentment and kingdom-focused purpose. Amen.", date: "" },
  { id: "274", verse: "Our soul waiteth for the Lord: he is our help and our shield. For our heart shall rejoice in him, because we have trusted in his holy name.", reference: "1 Samuel 16:7", devotional: "God sees what humans cannot: the heart. He values character over appearance and faithfulness over fame. Focus on cultivating a heart that pleases God above all else.", prayer: "Lord, search my heart and make it pure. Help me to value what You value: a faithful and sincere heart. Amen.", date: "" },
  { id: "275", verse: "For God is not unrighteous to forget your work and labour of love, which ye have shewed toward his name, in that ye have ministered to the saints, and do minister.", reference: "Jeremiah 29:12", devotional: "God promises to listen when you call on Him. He is attentive to your prayers and eager to respond. You have an audience with the King of kings whenever you pray.", prayer: "Lord, I call on You and come to You in prayer. Thank You for listening to me. I trust in Your response. Amen.", date: "" },
  { id: "276", verse: "The secret of the Lord is with them that fear him; and he will shew them his covenant.", reference: "Isaiah 43:1", devotional: "God calls you by name and claims you as His own. You are not a number or a face in the crowd. You are personally known, redeemed, and cherished by the Almighty.", prayer: "Lord, thank You for calling me by name and claiming me as Yours. I belong to You. I will not fear. Amen.", date: "" },
  { id: "277", verse: "For the mountains shall depart, and the hills be removed; but my kindness shall not depart from thee, neither shall the covenant of my peace be removed, saith the Lord that hath mercy on thee.", reference: "Ruth 1:16", devotional: "Ruth's declaration of loyalty and devotion is a beautiful picture of covenant love. True commitment means going where God leads and staying where He places you. Let your devotion to Him be wholehearted.", prayer: "Lord, where You go I will go. Your people are my people and You are my God. I commit my life fully to You. Amen.", date: "" },
  { id: "278", verse: "Yea, the Lord shall give that which is good; and our land shall yield her increase.", reference: "2 Chronicles 16:9", devotional: "God is actively searching for people whose hearts are fully devoted to Him. He wants to strengthen you. Commit your heart completely and experience His empowering strength.", prayer: "Lord, find my heart fully committed to You. Strengthen me with Your power as I devote myself completely to You. Amen.", date: "" },
  { id: "279", verse: "When thou liest down, thou shalt not be afraid: yea, thou shalt lie down, and thy sleep shall be sweet.", reference: "2 Chronicles 7:14", devotional: "God's prescription for healing begins with humility, prayer, seeking, and repentance. When His people turn to Him wholeheartedly, He responds with forgiveness and restoration.", prayer: "Lord, I humble myself and seek Your face. Forgive my sins and bring healing. I turn from my own ways to Yours. Amen.", date: "" },
  { id: "280", verse: "But thou, O Lord, shalt endure for ever; and thy remembrance unto all generations.", reference: "John 14:2", devotional: "Jesus is preparing an eternal home for you in the Father's house. This promise assures you that your future is secure. Your place in eternity is being personally prepared by Jesus Himself.", prayer: "Lord Jesus, thank You for preparing a place for me in Your Father's house. My eternal future is secure in You. Amen.", date: "" },
  { id: "281", verse: "And all things, whatsoever ye shall ask in prayer, believing, ye shall receive.", reference: "2 Corinthians 4:8", devotional: "Pressure and confusion may surround you, but they cannot destroy you. God ensures that you are never fully crushed or driven to ultimate despair. His grace keeps you standing.", prayer: "Lord, when I am pressed and perplexed, keep me from being crushed or despairing. Your grace sustains me. Amen.", date: "" },
  { id: "282", verse: "This is my comfort in my affliction: for thy word hath quickened me.", reference: "James 1:12", devotional: "Perseverance under trial leads to a glorious reward: the crown of life. God promises this crown to those who love Him and endure faithfully. Your trial is temporary but your reward is eternal.", prayer: "Lord, help me to persevere under trial. I look forward to the crown of life You have promised to those who love You. Amen.", date: "" },
  { id: "283", verse: "God is faithful, by whom ye were called unto the fellowship of his Son Jesus Christ our Lord.", reference: "John 10:27", devotional: "As Jesus' sheep, you can hear His voice. He knows you intimately and calls you to follow Him. Tune your heart to recognize His voice above all the noise of life.", prayer: "Jesus, help me to hear Your voice clearly. I am Your sheep and I choose to follow You today. Amen.", date: "" },
  { id: "284", verse: "I will sing of the mercies of the Lord for ever: with my mouth will I make known thy faithfulness to all generations.", reference: "Psalm 1:1", devotional: "Blessing comes from choosing your associations wisely. Guard yourself from the influence of those who mock God and lead others astray. Walk in the counsel of the righteous.", prayer: "Lord, guard me from ungodly counsel. Help me to walk in wisdom and associate with those who honor You. Amen.", date: "" },
  { id: "285", verse: "But whosoever drinketh of the water that I shall give him shall never thirst; but the water that I shall give him shall be in him a well of water springing up into everlasting life.", reference: "Psalm 1:2", devotional: "Meditating on God's Word day and night fills your mind with truth and transforms your perspective. Make Scripture your daily delight and watch your life become deeply rooted and fruitful.", prayer: "Lord, let Your law be my delight. Help me to meditate on Your Word day and night. Amen.", date: "" },
  { id: "286", verse: "But the mercy of the Lord is from everlasting to everlasting upon them that fear him, and his righteousness unto children's children.", reference: "Hosea 6:3", devotional: "Pressing on to know God brings refreshing like rain upon dry ground. His presence is as certain as the sunrise. Pursue Him with persistence and experience the renewal He brings.", prayer: "Lord, I press on to know You more. Come to me like refreshing rain and renew my spirit today. Amen.", date: "" },
  { id: "287", verse: "Be not overcome of evil, but overcome evil with good.", reference: "Psalm 143:1", devotional: "God is a faithful and righteous listener. When you cry out for mercy, He responds with compassion. His faithfulness ensures that your prayers are never ignored or forgotten.", prayer: "Lord, hear my prayer and listen to my cry for mercy. Come to my relief in Your faithfulness. Amen.", date: "" },
  { id: "288", verse: "For thy mercy is great unto the heavens, and thy truth unto the clouds.", reference: "Psalm 60:12", devotional: "Victory is assured when God is with you. He tramples down every enemy that rises against you. Your confidence in battle comes not from your strength but from His presence.", prayer: "Lord, with You I gain the victory. Trample down every enemy that stands against me. I trust in Your power. Amen.", date: "" },
  { id: "289", verse: "The blessing of the Lord, it maketh rich, and he addeth no sorrow with it.", reference: "Job 42:2", devotional: "God's purposes are unstoppable. No force in heaven or earth can thwart His plans. When His purpose is set, it will be accomplished. Rest in the certainty of His sovereign will.", prayer: "Lord, I know You can do all things. No purpose of Yours can be thwarted. I trust in Your sovereign plan. Amen.", date: "" },
  { id: "290", verse: "Great peace have they which love thy law: and nothing shall offend them.", reference: "Psalm 11:4", devotional: "God is enthroned in heaven, observing all that happens on earth. Nothing escapes His notice. He sees your struggles, your faithfulness, and your needs. You are always in His sight.", prayer: "Lord, You see everything from Your heavenly throne. Thank You for watching over me with care and attention. Amen.", date: "" },
  { id: "291", verse: "Blessed be God, even the Father of our Lord Jesus Christ, the Father of mercies, and the God of all comfort; who comforteth us in all our tribulation, that we may be able to comfort them which are in any trouble, by the comfort wherewith we ourselves are comforted of God.", reference: "Proverbs 12:22", devotional: "Integrity and honesty bring delight to God's heart. In a world full of deception, choose to be trustworthy. Your honesty honors God and builds a life of credibility.", prayer: "Lord, make me a person of integrity. Let my words be truthful and my character trustworthy. I want to delight Your heart. Amen.", date: "" },
  { id: "292", verse: "I will remember the works of the Lord: surely I will remember thy wonders of old. I will meditate also of all thy work, and talk of thy doings.", reference: "Luke 19:10", devotional: "Jesus' mission is clear: to find and rescue the lost. His heart beats for those who are far from God. As His followers, we share in this mission of love and redemption.", prayer: "Lord, give me Your heart for the lost. Use me to seek and share Your saving love with those who need it. Amen.", date: "" },
  { id: "293", verse: "Blessed are the poor in spirit: for theirs is the kingdom of heaven.", reference: "Psalm 91:2", devotional: "Declaring God as your refuge is an act of faith that activates His protection. Speak His promises over your life and trust in His fortress of safety and security.", prayer: "Lord, You are my refuge and fortress. I declare my trust in You. You are my God and I am safe in You. Amen.", date: "" },
  { id: "294", verse: "Trust in him at all times; ye people, pour out your heart before him: God is a refuge for us. Selah.", reference: "Psalm 86:5", devotional: "God's nature is to forgive. He is good and abounding in love toward everyone who calls upon Him. Don't hesitate to call out to Him; His love and forgiveness are ready.", prayer: "Lord, I call to You today. Thank You for being forgiving and good. Your love is abundant and Your mercy is endless. Amen.", date: "" },
  { id: "295", verse: "So shall my word be that goeth forth out of my mouth: it shall not return unto me void, but it shall accomplish that which I please, and it shall prosper in the thing whereto I sent it.", reference: "Colossians 3:14", devotional: "Love is the binding force that holds all other virtues together. Without love, even the best qualities fall apart. Make love the overarching theme of your life.", prayer: "Lord, help me to put on love above all other virtues. Let love bind everything together in perfect unity. Amen.", date: "" },
  { id: "296", verse: "Oh how great is thy goodness, which thou hast laid up for them that fear thee; which thou hast wrought for them that trust in thee before the sons of men!", reference: "Psalm 130:5", devotional: "Waiting for the Lord with your whole being is an expression of complete dependence. Place your hope in His Word and trust that He will act at the right time.", prayer: "Lord, my whole being waits for You. I put my hope in Your Word. I trust in Your faithful promises. Amen.", date: "" },
  { id: "297", verse: "But sanctify the Lord God in your hearts: and be ready always to give an answer to every man that asketh you a reason of the hope that is in you with meekness and fear.", reference: "Malachi 3:10", devotional: "God invites you to test His generosity. When you give faithfully, He opens the floodgates of heaven. His blessings overflow beyond what you can contain. Trust Him with your resources.", prayer: "Lord, I trust You with my giving. Open the floodgates of heaven and pour out Your blessings upon my life. Amen.", date: "" },
  { id: "298", verse: "In God we boast all the day long, and praise thy name for ever. Selah.", reference: "Deuteronomy 6:5", devotional: "Loving God with every part of your being is life's highest calling. Heart, soul, and might — all given fully to Him. This total devotion is the foundation of a meaningful life.", prayer: "Lord, I love You with all my heart, soul, and might. Help me to give You everything I have and am. Amen.", date: "" },
  { id: "299", verse: "He that trusteth in his own heart is a fool: but whoso walketh wisely, he shall be delivered.", reference: "Psalm 92:12", devotional: "God promises that the righteous will flourish and grow strong. Like deep-rooted trees, those who walk with God will be fruitful and resilient through every season.", prayer: "Lord, let me flourish like a palm tree and grow strong like a cedar. Root me deep in Your truth and love. Amen.", date: "" },
  { id: "300", verse: "O sing unto the Lord a new song: sing unto the Lord, all the earth. Sing unto the Lord, bless his name; shew forth his salvation from day to day.", reference: "1 Thessalonians 5:18", devotional: "Thankfulness in all circumstances is God's will for your life. Gratitude shifts your perspective from problems to possibilities. In everything, choose to give thanks.", prayer: "Lord, I give thanks in everything. This is Your will for me. Fill my heart with gratitude in every circumstance. Amen.", date: "" },
  { id: "301", verse: "For God sent not his Son into the world to condemn the world; but that the world through him might be saved.", reference: "John 3:30", devotional: "The Christian life is about making Jesus greater and yourself lesser. As His importance grows in your life, your self-centered desires diminish. This is the path to true joy.", prayer: "Lord, increase in my life. Help me to decrease so that You may shine more brightly through me. Amen.", date: "" },
  { id: "302", verse: "The Lord is my strength and song, and is become my salvation.", reference: "John 13:34", devotional: "Jesus' command to love is both new and timeless. His love is the standard and the model. Love as He has loved you: sacrificially, unconditionally, and without limits.", prayer: "Jesus, help me to love others as You have loved me. Let Your kind of love flow through me today. Amen.", date: "" },
  { id: "303", verse: "For I am not ashamed of the gospel of Christ: for it is the power of God unto salvation to every one that believeth; to the Jew first, and also to the Greek.", reference: "Zechariah 14:9", devotional: "A day is coming when the Lord will reign supreme over all the earth. His name will be the only name exalted. This future reality gives us hope and confidence today.", prayer: "Lord, I look forward to the day when You reign as King over the whole earth. Your name alone will be exalted. Amen.", date: "" },
  { id: "304", verse: "The Lord upholdeth all that fall, and raiseth up all those that be bowed down.", reference: "Psalm 121:1", devotional: "Looking to God is the first response in any situation. When you lift your eyes from your problems to His promise, help becomes visible. Your help comes from the Lord.", prayer: "Lord, I lift my eyes to You. You are my help and my hope. I look to You for everything I need. Amen.", date: "" },
  { id: "305", verse: "So that we may boldly say, The Lord is my helper, and I will not fear what man shall do unto me.", reference: "Psalm 10:16", devotional: "God's reign is eternal. While earthly kingdoms rise and fall, His kingdom endures forever. Take comfort in knowing that the ultimate King is on the throne.", prayer: "Lord, You are King forever and ever. I submit to Your eternal reign and trust in Your sovereign rule. Amen.", date: "" },
  { id: "306", verse: "I had fainted, unless I had believed to see the goodness of the Lord in the land of the living.", reference: "2 John 1:6", devotional: "Love and obedience are inseparable in God's economy. True love is demonstrated through walking in His commands. Obedience is not burdensome when it flows from a heart of love.", prayer: "Lord, help me to walk in obedience to Your commands. Let my obedience be an expression of my love for You. Amen.", date: "" },
  { id: "307", verse: "The Spirit of the Lord God is upon me; because the Lord hath anointed me to preach good tidings unto the meek; he hath sent me to bind up the brokenhearted, to proclaim liberty to the captives, and the opening of the prison to them that are bound.", reference: "1 John 1:7", devotional: "Walking in the light means living honestly and transparently before God and others. In the light, fellowship flourishes and the blood of Jesus cleanses completely.", prayer: "Lord, help me to walk in the light. Purify me with the blood of Jesus and deepen my fellowship with others. Amen.", date: "" },
  { id: "308", verse: "But I am like a green olive tree in the house of God: I trust in the mercy of God for ever and ever.", reference: "1 Corinthians 1:18", devotional: "The cross may seem foolish to the world, but to believers it is the very power of God. In the cross, you find salvation, healing, freedom, and eternal life.", prayer: "Lord, the message of the cross is power to me. Thank You for saving me through Christ's sacrifice. Amen.", date: "" },
  { id: "309", verse: "A merry heart maketh a cheerful countenance: but by sorrow of the heart the spirit is broken.", reference: "Psalm 103:2", devotional: "It is easy to forget God's blessings amid daily challenges. Take time to remember and recount His benefits. Gratitude fuels praise and praise deepens your relationship with God.", prayer: "Lord, I praise You and remember all Your benefits. Thank You for every blessing You have poured into my life. Amen.", date: "" },
  { id: "310", verse: "The righteous cry, and the Lord heareth, and delivereth them out of all their troubles.", reference: "Proverbs 17:9", devotional: "Forgiveness strengthens relationships while grudges destroy them. When you choose to forgive and let go, love grows. Don't let offenses separate you from those God has placed in your life.", prayer: "Lord, give me the grace to forgive offenses. Help me to seek love and preserve the relationships You have given me. Amen.", date: "" },
  { id: "311", verse: "And Jesus said unto them, Because of your unbelief: for verily I say unto you, If ye have faith as a grain of mustard seed, ye shall say unto this mountain, Remove hence to yonder place; and it shall remove; and nothing shall be impossible unto you.", reference: "Philippians 1:2", devotional: "Grace and peace are God's greeting to every believer. He offers you unmerited favor and supernatural peace as gifts. Receive them today and let them transform your experience.", prayer: "Lord, I receive Your grace and peace today. Let them fill my heart and transform my daily experience. Amen.", date: "" },
  { id: "312", verse: "By the word of the Lord were the heavens made; and all the host of them by the breath of his mouth.", reference: "2 Chronicles 20:15", devotional: "Some battles are too big for you to fight alone. That's when God steps in and says the battle belongs to Him. Release your struggle to Him and let Him fight for you.", prayer: "Lord, this battle belongs to You. I release my struggles to Your capable hands. Fight for me and bring victory. Amen.", date: "" },
  { id: "313", verse: "Therefore, my beloved brethren, be ye stedfast, unmoveable, always abounding in the work of the Lord, forasmuch as ye know that your labour is not in vain in the Lord.", reference: "Romans 12:10", devotional: "Devotion and honor toward others reflect the heart of Christ. Put others first and show genuine love in your relationships. This selfless attitude transforms communities.", prayer: "Lord, make me devoted to others in love. Help me to honor others above myself, as Christ has honored me. Amen.", date: "" },
  { id: "314", verse: "For ever, O Lord, thy word is settled in heaven.", reference: "2 Timothy 4:7", devotional: "Paul's declaration at the end of his life is the goal for every believer. Fight well, finish strong, and keep the faith. Live so that your final words echo this triumphant statement.", prayer: "Lord, help me to fight the good fight and finish the race. Give me endurance to keep the faith until the end. Amen.", date: "" },
  { id: "315", verse: "My sheep hear my voice, and I know them, and they follow me: and I give unto them eternal life; and they shall never perish, neither shall any man pluck them out of my hand.", reference: "Isaiah 40:28", devotional: "God never gets tired or burned out. His energy and understanding are infinite. When you are weary, draw from His inexhaustible supply of strength and wisdom.", prayer: "Lord, You never grow tired or weary. When I am exhausted, fill me with Your infinite strength and understanding. Amen.", date: "" },
  { id: "316", verse: "For as the heaven is high above the earth, so great is his mercy toward them that fear him.", reference: "Psalm 136:1", devotional: "God's goodness and enduring mercy are reasons for constant thanksgiving. His mercy never expires or diminishes. It lasts forever, covering every generation and every situation.", prayer: "Lord, I give You thanks for You are good. Your mercy endures forever and I am forever grateful. Amen.", date: "" },
  { id: "317", verse: "So then faith cometh by hearing, and hearing by the word of God.", reference: "Psalm 113:5-6", devotional: "The God who is enthroned above all creation stoops down to look upon you. His majesty does not make Him distant; it makes His nearness more remarkable.", prayer: "Lord, You are enthroned on high yet You stoop down to look upon me. Your nearness amazes me. Amen.", date: "" },
  { id: "318", verse: "O give thanks unto the Lord; for he is good: for his mercy endureth for ever.", reference: "Colossians 3:13", devotional: "Forgiveness is not optional for Christians; it is essential. Just as Christ forgave you freely and completely, extend that same grace to others who have wronged you.", prayer: "Lord, help me to forgive as You have forgiven me. Give me grace to bear with others and release all grievances. Amen.", date: "" },
  { id: "319", verse: "Iron sharpeneth iron; so a man sharpeneth the countenance of his friend.", reference: "Psalm 90:14", devotional: "Starting each day with God's unfailing love sets the tone for joy that lasts. Let His love be the first thing you receive each morning, and gladness will follow.", prayer: "Lord, satisfy me each morning with Your unfailing love. Let me sing for joy and be glad all my days. Amen.", date: "" },
  { id: "320", verse: "I sought the Lord, and he heard me, and delivered me from all my fears.", reference: "Acts 17:28", devotional: "Every breath, every step, every moment of your existence happens within God's sustaining presence. You are completely dependent on Him for everything. In Him, you truly live.", prayer: "Lord, in You I live and move and have my being. I depend on You for every breath. You sustain me. Amen.", date: "" },
  { id: "321", verse: "For the word of God is quick, and powerful, and sharper than any twoedged sword, piercing even to the dividing asunder of soul and spirit, and of the joints and marrow, and is a discerner of the thoughts and intents of the heart.", reference: "Ezekiel 36:26", devotional: "God specializes in heart transplants. He can replace your hard, calloused heart with one that is soft, responsive, and alive to His Spirit. Allow Him to do this transforming work.", prayer: "Lord, give me a new heart and a new spirit. Remove my heart of stone and replace it with a heart of flesh. Amen.", date: "" },
  { id: "322", verse: "God hath spoken once; twice have I heard this; that power belongeth unto God. Also unto thee, O Lord, belongeth mercy: for thou renderest to every man according to his work.", reference: "Joel 2:13", devotional: "God always welcomes you back with open arms. His grace, compassion, and love are waiting for you when you return to Him. Never hesitate to come back to His embrace.", prayer: "Lord, I return to You with all my heart. Thank You for being gracious, compassionate, and abounding in love. Amen.", date: "" },
  { id: "323", verse: "When thou passest through the waters, I will be with thee; and through the rivers, they shall not overflow thee: when thou walkest through the fire, thou shalt not be burned; neither shall the flame kindle upon thee.", reference: "Psalm 31:19", devotional: "God has an abundance of good things stored up for those who revere Him. His blessings are not stingy but overflowing. Take refuge in Him and receive His abundant goodness.", prayer: "Lord, I take refuge in You. Thank You for the abundant good things You have stored up for me. Amen.", date: "" },
  { id: "324", verse: "Cause me to hear thy lovingkindness in the morning; for in thee do I trust: cause me to know the way wherein I should walk; for I lift up my soul unto thee.", reference: "Psalm 33:4", devotional: "God's Word is completely reliable and His actions are completely faithful. When everything else is uncertain, His Word and His character remain rock solid.", prayer: "Lord, Your Word is right and true. You are faithful in all You do. I build my life on Your reliability. Amen.", date: "" },
  { id: "325", verse: "But I say unto you, Love your enemies, bless them that curse you, do good to them that hate you, and pray for them which despitefully use you, and persecute you.", reference: "Isaiah 30:15", devotional: "True strength is found not in frantic activity but in quiet trust. When you are still before God and trust His plan, supernatural strength fills you. Be quiet and be strong.", prayer: "Lord, I find my strength in quietness and trust. Still my heart before You and fill me with Your power. Amen.", date: "" },
  { id: "326", verse: "I have chosen the way of truth: thy judgments have I laid before me.", reference: "Proverbs 10:9", devotional: "Integrity provides a foundation of security in life. When you walk with honesty and uprightness, you walk without fear of exposure. Choose the straight path of integrity.", prayer: "Lord, help me to walk in integrity. Let my life be honest and upright so I may walk securely. Amen.", date: "" },
  { id: "327", verse: "Forbearing one another, and forgiving one another, if any man have a quarrel against any: even as Christ forgave you, so also do ye.", reference: "Luke 1:46-47", devotional: "Mary's song of praise is a model for every believer. Let your soul magnify the Lord and your spirit rejoice in Him. He is worthy of your highest praise and deepest joy.", prayer: "Lord, my soul glorifies You and my spirit rejoices in You, my Savior. You are worthy of all praise. Amen.", date: "" },
  { id: "328", verse: "My voice shalt thou hear in the morning, O Lord; in the morning will I direct my prayer unto thee, and will look up.", reference: "Psalm 119:97", devotional: "Loving God's Word is a sign of spiritual maturity. When you meditate on His law throughout the day, it shapes your thoughts, your decisions, and your character.", prayer: "Lord, give me a deep love for Your Word. Help me to meditate on it all day long and be transformed. Amen.", date: "" },
  { id: "329", verse: "And this is the confidence that we have in him, that, if we ask any thing according to his will, he heareth us.", reference: "Psalm 91:7", devotional: "God's protection is so complete that even when destruction surrounds you, it cannot touch you. His shield covers you in the most dangerous circumstances. Trust His sovereign protection.", prayer: "Lord, even when danger surrounds me, I trust in Your protection. Nothing can touch me without passing through Your hands. Amen.", date: "" },
  { id: "330", verse: "Let every thing that hath breath praise the Lord. Praise ye the Lord.", reference: "Ephesians 4:15", devotional: "Truth and love must always go together. Speaking truth without love wounds, and love without truth misleads. Together they produce maturity and growth in the body of Christ.", prayer: "Lord, help me to speak truth in love. Let this combination help me and others grow into maturity in Christ. Amen.", date: "" },
  { id: "331", verse: "He that followeth after righteousness and mercy findeth life, righteousness, and honour.", reference: "Psalm 63:3", devotional: "God's love is more precious than life itself. When you grasp how valuable His love is, praise becomes your natural response. His love is your greatest treasure.", prayer: "Lord, Your love is better than life. My lips will glorify You because Your love is my greatest treasure. Amen.", date: "" },
  { id: "332", verse: "Therefore will not we fear, though the earth be removed, and though the mountains be carried into the midst of the sea; though the waters thereof roar and be troubled, though the mountains shake with the swelling thereof. Selah.", reference: "Romans 12:21", devotional: "The way to defeat evil is not with more evil but with good. Responding to wrong with right is a powerful testimony. Let goodness be your weapon against every form of evil.", prayer: "Lord, help me to overcome evil with good. Let my goodness be a powerful testimony of Your love. Amen.", date: "" },
  { id: "333", verse: "And I will pray the Father, and he shall give you another Comforter, that he may abide with you for ever; even the Spirit of truth; whom the world cannot receive, because it seeth him not, neither knoweth him: but ye know him; for he dwelleth with you, and shall be in you.", reference: "Revelation 1:8", devotional: "God is the beginning and the end of all things. He exists outside of time, sovereign over past, present, and future. In Him, every story finds its ultimate meaning.", prayer: "Lord, You are the Alpha and Omega. You hold the beginning and end of my story. I trust You with every chapter. Amen.", date: "" },
  { id: "334", verse: "The Lord is righteous in all his ways, and holy in all his works.", reference: "Proverbs 17:17", devotional: "True friendship endures through every season. A genuine friend loves consistently, not just when it is convenient. Be that kind of friend and seek friends who reflect God's faithfulness.", prayer: "Lord, help me to be a true friend who loves at all times. Thank You for the faithful friends You have given me. Amen.", date: "" },
  { id: "335", verse: "For I reckon that the sufferings of this present time are not worthy to be compared with the glory which shall be revealed in us.", reference: "Isaiah 40:1-2", devotional: "God speaks comfort to His people in their trials. He proclaims that seasons of hardship come to an end. His tender words bring hope and assurance that better days are ahead.", prayer: "Lord, speak comfort to my heart. Remind me that my hard season will end and Your tenderness will carry me through. Amen.", date: "" },
  { id: "336", verse: "Order my steps in thy word: and let not any iniquity have dominion over me.", reference: "Psalm 113:4", devotional: "God's exaltation is above every nation and His glory surpasses the heavens. No earthly power compares to His majesty. Worship the One who reigns supreme over all creation.", prayer: "Lord, You are exalted over all nations. Your glory is above the heavens. I worship You in all Your majesty. Amen.", date: "" },
  { id: "337", verse: "Now no chastening for the present seemeth to be joyous, but grievous: nevertheless afterward it yieldeth the peaceable fruit of righteousness unto them which are exercised thereby.", reference: "Daniel 3:17", devotional: "The faith of Shadrach, Meshach, and Abednego inspires unwavering trust. They knew God was able to deliver them, yet their faith did not depend on the outcome. Trust God even in the fire.", prayer: "Lord, I trust that You are able to deliver me from every trial. My faith rests in Your power, not my circumstances. Amen.", date: "" },
  { id: "338", verse: "When I said, My foot slippeth; thy mercy, O Lord, held me up. In the multitude of my thoughts within me thy comforts delight my soul.", reference: "Amos 5:24", devotional: "God desires justice and righteousness to flow like unstoppable rivers through your life and community. These are not occasional acts but a continuous stream of godly living that impacts everyone around you.", prayer: "Lord, let justice and righteousness flow through my life like a never-failing stream. Use me to bring Your justice to others. Amen.", date: "" },
  { id: "339", verse: "And thine ears shall hear a word behind thee, saying, This is the way, walk ye in it, when ye turn to the right hand, and when ye turn to the left.", reference: "Isaiah 9:2", devotional: "No matter how deep the darkness you've walked through, God's light breaks through. He brings illumination to the darkest places and hope to the most hopeless situations.", prayer: "Lord, shine Your great light into my darkness. Let Your light break through every shadow in my life. Amen.", date: "" },
  { id: "340", verse: "Let, I pray thee, thy merciful kindness be for my comfort, according to thy word unto thy servant.", reference: "Romans 14:8", devotional: "Your life and death belong to the Lord. This truth gives purpose to every breath and removes the fear of death. You are His, fully and eternally.", prayer: "Lord, whether I live or die, I belong to You. Let my life and my death bring glory to Your name. Amen.", date: "" },
  { id: "341", verse: "When a man's ways please the Lord, he maketh even his enemies to be at peace with him.", reference: "Revelation 21:5", devotional: "God is in the business of renewal. He makes all things new, including you. Whatever is worn out, broken, or weary in your life, He is renewing it even now.", prayer: "Lord, make everything in my life new. Renew what is worn out and restore what is broken. I trust in Your renewal. Amen.", date: "" },
  { id: "342", verse: "Many, O Lord my God, are thy wonderful works which thou hast done, and thy thoughts which are to us-ward: they cannot be reckoned up in order unto thee: if I would declare and speak of them, they are more than can be numbered.", reference: "Exodus 17:15", devotional: "God is your banner of victory and identity. Under His banner, you are protected, identified, and victorious. Rally under His banner and march forward in confidence.", prayer: "Lord, You are my banner. Under Your standard I am victorious. I march forward in confidence under Your authority. Amen.", date: "" },
  { id: "343", verse: "Come unto me, all ye that labour and are heavy laden, and I will give you rest. Take my yoke upon you, and learn of me; for I am meek and lowly in heart: and ye shall find rest unto your souls. For my yoke is easy, and my burden is light.", reference: "Psalm 36:5", devotional: "God's love is not small or limited. It reaches to the heavens, vast and immeasurable. His faithfulness stretches beyond what your eyes can see. You are covered by limitless love.", prayer: "Lord, Your love reaches to the heavens. Thank You for Your faithfulness that stretches to the skies. Amen.", date: "" },
  { id: "344", verse: "The Lord hath prepared his throne in the heavens; and his kingdom ruleth over all.", reference: "Colossians 3:23", devotional: "Your work is worship when done for the Lord. Whether your task is great or small, give it your full effort as an offering to God. He sees and rewards your faithfulness.", prayer: "Lord, help me to work with all my heart as unto You. Let my daily labor be an act of worship. Amen.", date: "" },
  { id: "345", verse: "Whether therefore ye eat, or drink, or whatsoever ye do, do all to the glory of God.", reference: "Psalm 145:20", devotional: "God's preserving power is directed toward those who love Him. He guards your life, protects your soul, and sustains your faith. Love Him and experience His faithful preservation.", prayer: "Lord, I love You. Preserve me by Your power. Guard my life and sustain my faith. I trust in Your care. Amen.", date: "" },
  { id: "346", verse: "I will praise thee with my whole heart: before the gods will I sing praise unto thee. I will worship toward thy holy temple, and praise thy name for thy lovingkindness and for thy truth: for thou hast magnified thy word above all thy name.", reference: "Psalm 103:12", devotional: "God's forgiveness is complete and total. He doesn't just forgive your sins; He removes them as far as the east is from the west. That is an infinite distance of grace.", prayer: "Lord, thank You for removing my sins so completely. Your forgiveness is total and Your grace is infinite. Amen.", date: "" },
  { id: "347", verse: "Ye have not chosen me, but I have chosen you, and ordained you, that ye should go and bring forth fruit, and that your fruit should remain: that whatsoever ye shall ask of the Father in my name, he may give it you.", reference: "Ephesians 3:16", devotional: "God strengthens you from the inside out through His Spirit. His glorious riches are the source of your inner power. You are strengthened not by circumstances but by His Spirit within.", prayer: "Lord, strengthen me with power through Your Spirit in my inner being. Draw from Your glorious riches to empower me. Amen.", date: "" },
  { id: "348", verse: "Thou tellest my wanderings: put thou my tears into thy bottle: are they not in thy book?", reference: "Titus 3:5", devotional: "Salvation is entirely by God's mercy, not our merit. Through the Holy Spirit, He washes, renews, and transforms us from the inside out. Rest in the grace that saved you.", prayer: "Lord, thank You for saving me by Your mercy. Renew me daily through Your Holy Spirit. I rest in Your grace alone. Amen.", date: "" },
  { id: "349", verse: "I beseech you therefore, brethren, by the mercies of God, that ye present your bodies a living sacrifice, holy, acceptable unto God, which is your reasonable service.", reference: "John 8:36", devotional: "The freedom Jesus offers is real and complete. It is not a temporary reprieve but a permanent liberation. In Christ, you are truly free from sin, shame, and condemnation.", prayer: "Jesus, thank You for setting me free. I walk in the freedom You have given me. I am truly free in You. Amen.", date: "" },
  { id: "350", verse: "How sweet are thy words unto my taste! yea, sweeter than honey to my mouth!", reference: "Ephesians 1:3", devotional: "In Christ, you have access to every spiritual blessing. Nothing is withheld from you. God's blessings are comprehensive and complete. Receive all that He has provided.", prayer: "Lord, thank You for blessing me with every spiritual blessing in Christ. Help me to receive and walk in Your fullness. Amen.", date: "" },
  { id: "351", verse: "For the Lord shall be thy confidence, and shall keep thy foot from being taken.", reference: "Psalm 23:1", devotional: "When the Lord is your shepherd, every need is met. He provides, protects, and guides with perfect care. You lack nothing when you are in His fold.", prayer: "Lord, You are my shepherd and I lack nothing. Thank You for Your complete provision and perfect care. Amen.", date: "" },
  { id: "352", verse: "Thou art the God that doest wonders: thou hast declared thy strength among the people.", reference: "Jeremiah 20:11", devotional: "God stands with you as a mighty warrior against every enemy. Those who oppose you will not prevail because the Lord fights on your behalf. Take courage in His strength.", prayer: "Lord, You are with me like a mighty warrior. My enemies will not prevail. I take courage in Your strength. Amen.", date: "" },
  { id: "353", verse: "Through faith we understand that the worlds were framed by the word of God, so that things which are seen were not made of things which do appear.", reference: "1 Thessalonians 5:16-18", devotional: "Rejoicing, praying, and giving thanks are God's will for your life. These three practices create a rhythm of faith that sustains you through every season.", prayer: "Lord, help me to rejoice always, pray continually, and give thanks in all circumstances. This is Your will for me. Amen.", date: "" },
  { id: "354", verse: "But I will hope continually, and will yet praise thee more and more.", reference: "Isaiah 55:9", devotional: "God's ways and thoughts are infinitely above yours. When His plans don't make sense, remember that His perspective is higher and His wisdom is deeper than anything you can comprehend.", prayer: "Lord, Your ways are higher than mine. Help me to trust Your wisdom even when I cannot understand. Amen.", date: "" },
  { id: "355", verse: "He shall feed his flock like a shepherd: he shall gather the lambs with his arm, and carry them in his bosom, and shall gently lead those that are with young.", reference: "Colossians 1:13", devotional: "God has rescued you from the power of darkness and transferred you to the kingdom of His beloved Son. You are no longer under the enemy's authority but under Christ's loving reign.", prayer: "Lord, thank You for rescuing me from darkness. I live in the kingdom of Your beloved Son. I am free. Amen.", date: "" },
  { id: "356", verse: "Because he hath set his love upon me, therefore will I deliver him: I will set him on high, because he hath known my name. He shall call upon me, and I will answer him: I will be with him in trouble; I will deliver him, and honour him.", reference: "Deuteronomy 32:4", devotional: "God is the Rock of perfection. Every work of His hands is perfect and every way is just. He does no wrong. Build your life on this unshakable foundation of His character.", prayer: "Lord, You are my Rock. Your works are perfect and Your ways are just. I build my life on Your faithfulness. Amen.", date: "" },
  { id: "357", verse: "Blessed are the merciful: for they shall obtain mercy.", reference: "Micah 7:18", devotional: "There is no God like ours who freely pardons sin and forgives transgression. His mercy is unique and His grace is matchless. Celebrate the God who forgives completely.", prayer: "Lord, there is no God like You. Thank You for pardoning my sin and forgiving my transgressions. Your mercy is matchless. Amen.", date: "" },
  { id: "358", verse: "Depart from evil, and do good; seek peace, and pursue it.", reference: "John 1:5", devotional: "No matter how deep the darkness, God's light cannot be extinguished. His truth, His love, and His presence shine through every shadow. The darkness will never overcome His light.", prayer: "Lord, let Your light shine in my darkness. No shadow can overcome Your brilliant and eternal light. Amen.", date: "" },
  { id: "359", verse: "As ye have therefore received Christ Jesus the Lord, so walk ye in him: rooted and built up in him, and stablished in the faith, as ye have been taught, abounding therein with thanksgiving.", reference: "Song of Solomon 4:7", devotional: "God sees you as beautiful and flawless in Christ. His love covers every imperfection and His grace makes you whole. See yourself through His eyes of love and admiration.", prayer: "Lord, help me to see myself as You see me: beautiful and without flaw in Christ. I receive Your affirming love. Amen.", date: "" },
  { id: "360", verse: "For thou, Lord, hast made me glad through thy work: I will triumph in the works of thy hands. O Lord, how great are thy works! and thy thoughts are very deep.", reference: "Judges 18:6", devotional: "When God approves your journey, you can go in peace. His blessing upon your path gives you confidence and rest. Walk forward knowing that He has given His approval.", prayer: "Lord, I go in peace because my journey has Your approval. Bless my path and guide my steps forward. Amen.", date: "" },
  { id: "361", verse: "Blessed be the God and Father of our Lord Jesus Christ, which according to his abundant mercy hath begotten us again unto a lively hope by the resurrection of Jesus Christ from the dead.", reference: "Psalm 138:8", devotional: "God will complete what He has started in your life. His purpose for you will be fulfilled because His love endures forever. Trust that He will see it through to the end.", prayer: "Lord, fulfill Your purpose for me. Your steadfast love endures forever and I trust You to complete Your work. Amen.", date: "" },
  { id: "362", verse: "Gracious is the Lord, and righteous; yea, our God is merciful. The Lord preserveth the simple: I was brought low, and he helped me.", reference: "Psalm 119:2", devotional: "Wholehearted seeking of God brings blessing. When you pursue Him with all your heart and follow His ways, you experience the fullness of His favor and joy.", prayer: "Lord, I seek You with all my heart. Help me to keep Your statutes and walk in Your blessing. Amen.", date: "" },
  { id: "363", verse: "But if the Spirit of him that raised up Jesus from the dead dwell in you, he that raised up Christ from the dead shall also quicken your mortal bodies by his Spirit that dwelleth in you.", reference: "Psalm 100:3", devotional: "You belong to God. He made you and claims you as His own. You are part of His flock, under His care, in His pasture. Rest in the security of belonging to Him.", prayer: "Lord, I am Yours. You made me and I belong to You. I am a sheep of Your pasture and I rest in Your care. Amen.", date: "" },
  { id: "364", verse: "Thy kingdom is an everlasting kingdom, and thy dominion endureth throughout all generations.", reference: "Philippians 4:23", devotional: "Grace is God's final word over your life. The grace of Jesus Christ accompanies your spirit in every moment. Let His grace be the atmosphere in which you live and breathe.", prayer: "Lord Jesus, let Your grace be with my spirit. May I live and breathe in the atmosphere of Your grace. Amen.", date: "" },
  { id: "365", verse: "And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away.", reference: "Revelation 22:21", devotional: "The Bible's final words are a benediction of grace. God's grace through Jesus is His last word and His lasting word. Live under the canopy of this eternal grace.", prayer: "Lord Jesus, Your grace is the first and final word over my life. I live under the canopy of Your eternal grace. Amen.", date: "" },
];
